import { useState, useEffect, useRef, useCallback } from 'react';
import {
  ArrowLeft,
  Truck,
  CheckCircle2,
  Clock,
  Package,
  CalendarDays,
  RefreshCw,
  Store,
  ClipboardList,
  Plus,
  Search,
  Loader2,
  Play,
  History,
  ChevronDown,
  ListChecks,
  Trash2,
  Settings2,
  Leaf,
  MapPin,
  MoreVertical,
  Sparkles,
  Sun,
  Moon,
  Check,
  X,
} from 'lucide-react';
import { logExpeditionStatusChange } from '@/shared/lib/expedition-log-service';
import { Button } from '@/shared/ui/button';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { Badge } from '@/shared/ui/badge';
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  CardDescription,
} from '@/shared/ui/card';
import { ScrollArea } from '@/shared/ui/scroll-area';
import { toast } from 'sonner';
import { Progress } from '@/shared/ui/progress';
import { Checkbox } from '@/shared/ui/checkbox';
import { Input } from '@/shared/ui/input';
import { cn } from '@/shared/lib/utils';
import { supabase } from '@/integrations/supabase/client';
import { useAuth } from '@/shared/hooks/useAuth';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/shared/ui/dropdown-menu';

// --- TYPES ---
import {
  ShipmentStatus,
  ActivityLog,
  Shipment,
  RequisicaoSimple,
} from '@/shared/types/logistics';
import {
  generateStops,
  isRequisicaoFinalizada,
  normalizeRequisicaoStatus,
} from '@/shared/lib/logistics-utils';
import { MetroLineNode } from '@/features/logistica/ui/MetroLineNode';
import { RouteConfigModal } from '@/features/logistica/ui/RouteConfigModal';
import { DistributionPlanTab } from '@/features/logistica/ui/DistributionPlanTab';
import { usePermissions } from '@/shared/hooks/usePermissions';
import { withTrace } from '@/shared/lib/telemetry/tracer';
import { wideInfo, wideError, wideDebug } from '@/shared/lib/telemetry/wide-events';
import { enrichWideEvent } from '@/shared/lib/telemetry/enrichWideEvent';
import {
  recordOperation,
  recordError,
  recordOperationDuration,
} from '@/shared/lib/telemetry/metrics';
import { useTelemetryAttrs } from '@/shared/lib/telemetry/useTelemetryAttrs';

// --- PALETTE (from MobileHome) ---
const COLORS = {
  green: '#57715B',
  cream: '#F5F5F0',
  wood: '#E6DCCF',
  gold: '#C5A065',
  text: '#2D362E',
};

// --- COMPONENTS ---

function StatusBadge({ status }: { status: ShipmentStatus }) {
  const styles = {
    separation: 'bg-[#F5F5F0] text-[#8B4513] border-[#E6DCCF]',
    loading: 'bg-blue-50 text-blue-600 border-blue-100',
    dispatch: 'bg-indigo-50 text-indigo-600 border-indigo-100',
    in_transit:
      'bg-[#57715B]/10 text-[#57715B] border-[#57715B]/20 animate-pulse',
    unloading: 'bg-pink-50 text-pink-600 border-pink-100',
    completed: 'bg-emerald-50 text-emerald-600 border-emerald-100',
  };

  const labels = {
    separation: 'Separação',
    loading: 'Carregamento',
    dispatch: 'Despacho',
    in_transit: 'Em Trânsito',
    unloading: 'Descarregando',
    completed: 'Finalizado',
  };

  return (
    <span
      className={cn(
        'px-2.5 py-0.5 rounded-full text-[11px] font-bold uppercase tracking-wider border shadow-sm',
        styles[status],
      )}
    >
      {labels[status]}
    </span>
  );
}

interface GroupedLog {
  main: ActivityLog;
  items: ActivityLog[];
}

function LogItem({ group }: { group: GroupedLog }) {
  const [expanded, setExpanded] = useState(false);
  const { main, items } = group;
  const hasItems = items.length > 0;
  const isSeparation =
    main.title.includes('Requisição') || main.title.includes('Separação');

  // Auto-expand active sessions or recent ones could be nice, but let's keep closed by default to avoid clutter

  return (
    <div className="relative pl-6 py-2 group">
      {/* Timeline Line */}
      <div className="absolute left-[7px] top-8 bottom-[-8px] w-px bg-[#E6DCCF] group-last:hidden" />

      {/* Dot */}
      <div
        className={cn(
          'absolute left-0 top-3 w-3.5 h-3.5 rounded-full border-[3px] border-white shadow-sm ring-1 ring-[#E6DCCF] transition-colors z-10',
          main.type === 'success'
            ? 'bg-emerald-500'
            : main.type === 'warning'
              ? 'bg-[#C5A065]'
              : main.type === 'error'
                ? 'bg-red-500'
                : 'bg-[#57715B]',
        )}
      />

      <div
        onClick={() => hasItems && setExpanded(!expanded)}
        className={cn(
          'flex flex-col gap-1 rounded-xl p-3 transition-all border border-transparent select-none',
          hasItems
            ? 'cursor-pointer hover:bg-[#F5F5F0] hover:border-[#E6DCCF]'
            : '',
        )}
      >
        <div className="flex items-center justify-between">
          <span className="text-sm font-bold text-[#2D362E] flex items-center gap-2">
            {main.title}
            {hasItems && (
              <Badge
                variant="secondary"
                className="text-[9px] h-4 px-1 bg-[#E6DCCF] text-[#57715B] hover:bg-[#dcd0c0]"
              >
                {items.length} eventos
              </Badge>
            )}
            {hasItems && (
              <ChevronDown
                className={cn(
                  'w-3 h-3 text-[#57715B] transition-transform',
                  expanded && 'rotate-180',
                )}
              />
            )}
          </span>
          <span className="text-[10px] text-[#57715B]/60 font-mono font-medium">
            {new Date(main.timestamp).toLocaleTimeString('pt-BR', {
              hour: '2-digit',
              minute: '2-digit',
            })}
          </span>
        </div>

        <p className="text-xs text-[#57715B] leading-relaxed opacity-80">
          {main.description}
        </p>

        {/* User Info */}
        {main.user && (
          <div className="flex items-center gap-1.5 mt-1">
            <div className="w-4 h-4 rounded-full bg-[#E6DCCF] flex items-center justify-center text-[8px] font-bold text-[#57715B] uppercase">
              {main.user.slice(0, 2)}
            </div>
            <span className="text-[10px] text-[#57715B]/60 font-bold uppercase tracking-wide">
              {main.user}
            </span>
            {main.metadata?.store_name && (
              <span className="px-1.5 py-px rounded-full bg-white text-[9px] text-[#C5A065] border border-[#C5A065]/20 font-medium">
                {main.metadata.store_name}
              </span>
            )}
          </div>
        )}
      </div>

      {hasItems && expanded && (
        <div className="ml-4 mt-1 border-l-2 border-[#E6DCCF] pl-4 space-y-2 py-2 animate-in slide-in-from-top-2 duration-300">
          {items.map((sub) => (
            <div
              key={sub.id}
              className="flex items-start gap-2 text-xs py-1 hover:bg-white/50 rounded-lg pr-2 transition-colors"
            >
              {sub.type === 'item_action' ? (
                <CheckCircle2
                  className={cn(
                    'w-3 h-3 mt-0.5',
                    sub.description.includes('não tem') ||
                      sub.type === 'warning'
                      ? 'text-amber-500'
                      : 'text-emerald-500',
                  )}
                />
              ) : (
                <div className="w-1.5 h-1.5 rounded-full bg-[#57715B]/30 mt-1.5 ml-0.5" />
              )}

              <div className="flex flex-col w-full">
                <div className="flex justify-between items-start w-full gap-2">
                  <span className="text-[#2D362E] flex-1 leading-snug">
                    {sub.description}
                  </span>
                  <span className="text-[9px] text-[#57715B]/40 font-mono whitespace-nowrap">
                    {new Date(sub.timestamp).toLocaleTimeString('pt-BR', {
                      hour: '2-digit',
                      minute: '2-digit',
                    })}
                  </span>
                </div>
                <span className="text-[9px] text-[#57715B]/60 uppercase tracking-wider font-medium mt-0.5">
                  {sub.user}
                </span>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default function LogisticsControlTower() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const { userProfile } = useAuth();
  const { isAdmin, loading: permissionsLoading } = usePermissions();
  const drpEnabled = isAdmin();

  const [viewMode, setViewMode] = useState<
    'drp' | 'dashboard' | 'creation' | 'tracking' | 'history'
  >('dashboard');
  const viewModeInitializedRef = useRef(false);

  // Reconcilia view inicial após permissions carregarem (?view=drp|shipments|history)
  useEffect(() => {
    if (permissionsLoading) return;
    if (viewModeInitializedRef.current) return;
    viewModeInitializedRef.current = true;
    const v = searchParams.get('view');
    if (v === 'drp' && drpEnabled) setViewMode('drp');
    else if (v === 'shipments' || v === 'dashboard') setViewMode('dashboard');
    else if (v === 'history') setViewMode('history');
    else setViewMode(drpEnabled ? 'drp' : 'dashboard');
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [permissionsLoading, drpEnabled]);
  const [selectedReqs, setSelectedReqs] = useState<number[]>([]);
  const [loadingReqs, setLoadingReqs] = useState(false);
  const [activeExpeditions, setActiveExpeditions] = useState<any[]>([]);
  const [openReqs, setOpenReqs] = useState<RequisicaoSimple[]>([]);
  const [activeShipment, setActiveShipment] = useState<Shipment | null>(null);
  const [isLeaving, setIsLeaving] = useState(false);
  const [logs, setLogs] = useState<ActivityLog[]>([]);
  const [historyList, setHistoryList] = useState<any[]>([]);
  const [loadingHistory, setLoadingHistory] = useState(false);
  const [historyFilterDate, setHistoryFilterDate] = useState<string>('');
  const [isEditingExpedition, setIsEditingExpedition] = useState(false);
  const [isRouteConfigOpen, setIsRouteConfigOpen] = useState(false);
  const [routeOrder, setRouteOrder] = useState<string[]>([]);
  const [selectedDate, setSelectedDate] = useState<string>(() => {
    const d = new Date();
    return d.toISOString().split('T')[0];
  });
  const [isEditingVehicle, setIsEditingVehicle] = useState(false);
  const [newVehicleName, setNewVehicleName] = useState('');

  const telemetryAttrs = useTelemetryAttrs();

  // Ref to track active expedition for realtime subscription
  const activeExpIdRef = useRef<string | null>(null);

  const calculateProgress = (status: ShipmentStatus): number => {
    switch (status) {
      case 'separation':
        return 20;
      case 'loading':
        return 40;
      case 'dispatch':
        return 60;
      case 'in_transit':
        return 80;
      case 'unloading':
        return 90;
      case 'completed':
        return 100;
      default:
        return 0;
    }
  };

  // Realtime subscription for requisition status changes
  useEffect(() => {
    if (!activeShipment?.id) {
      activeExpIdRef.current = null;
      return;
    }

    activeExpIdRef.current = activeShipment.id;
    const expId = activeShipment.id;

    // Subscribe to requisition changes for this expedition
    const channel = supabase
      .channel(`expedition-reqs-${expId}`)
      .on(
        'postgres_changes' as any,
        {
          event: 'UPDATE',
          schema: 'public',
          table: 'requisicoes',
          filter: `expedicao_id=eq.${expId}`,
        },
        (payload: any) => {
          wideDebug('logistica.realtime.requisicaoAtualizada', 'Requisição atualizada via realtime', { domain: 'logistica', attributes: { loja: payload.new?.loja_solicitante, status: payload.new?.status } });
          // Reload expedition data when any requisition is updated
          if (activeExpIdRef.current === expId) {
            loadExpedition(expId);
          }
        },
      )
      .on(
        'postgres_changes' as any,
        {
          event: 'INSERT',
          schema: 'public',
          table: 'expedicao_logs',
          filter: `expedicao_id=eq.${expId}`,
        },
        (payload: any) => {
          wideDebug('logistica.realtime.novoLog', 'Novo log de expedição recebido via realtime', { domain: 'logistica', attributes: { title: payload.new?.title } });
          // Reload expedition data when new logs are inserted
          if (activeExpIdRef.current === expId) {
            loadExpedition(expId);
          }
        },
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeShipment?.id]);

  const loadExpedition = async (expId: string) => {
    const { data: exp, error } = await (supabase as any)
      .from('expedicoes')
      .select('*')
      .eq('id', expId)
      .single();
    if (error || !exp) return;

    const { data: linkedReqs } = await (supabase as any)
      .from('requisicoes')
      .select(
        'id, loja_solicitante, data_recebimento, created_at, status, requisicoes_itens(count)',
      )
      .eq('expedicao_id', exp.id);

    const mappedReqs: RequisicaoSimple[] = linkedReqs
      ? linkedReqs.map((r: any) => ({
          id: r.id,
          loja_solicitante: r.loja_solicitante,
          data_recebimento: r.data_recebimento,
          created_at: r.created_at,
          status: r.status,
          item_count: r.requisicoes_itens[0]?.count || 0,
        }))
      : [];

    const reqIds = mappedReqs.map((r) => r.id);

    // Fetch logs - Buscar individualmente por cada requisição para evitar limite do Supabase
    const logPromises: Promise<any>[] = [];

    // Query 1: Logs linked directly to expedition
    logPromises.push(
      (supabase as any)
        .from('expedicao_logs')
        .select('*')
        .eq('expedicao_id', exp.id)
        .order('created_at', { ascending: false }),
    );

    // Query para CADA requisição individualmente (evita limite de 1000 do Supabase em queries com IN)
    // Busca TODOS os logs de cada requisição
    if (reqIds.length > 0) {
      reqIds.forEach((reqId) => {
        logPromises.push(
          (supabase as any)
            .from('expedicao_logs')
            .select('*')
            .eq('requisicao_id', reqId)
            .order('created_at', { ascending: false }),
        );
      });
    }

    const logResults = await Promise.all(logPromises);
    const allDbLogs: any[] = [];

    logResults.forEach((result) => {
      if (result.data) {
        allDbLogs.push(...result.data);
      }
    });

    // Process logs into a flat list first, deduplicating IDs
    const uniqueLogs = new Map<string, ActivityLog>();

    allDbLogs.forEach((l: any) => {
      uniqueLogs.set(l.id, {
        id: l.id,
        timestamp: l.created_at || l.timestamp, // Prefer created_at
        title: l.title,
        description: l.description,
        type: l.type,
        user: l.user_name,
        microLogs: l.metadata?.microLogs || [],
        metadata: l.metadata,
        // @ts-expect-error - Adding dynamic property for grouping
        requisicao_id: l.requisicao_id,
      } as ActivityLog);
    });

    // Convert Map to Array and Sort
    const finalLogs = Array.from(uniqueLogs.values()).sort(
      (a, b) =>
        new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime(),
    );

    setLogs(finalLogs);

    // Verifica se todas requisições estão finalizadas (usando função padronizada)
    const allReqsFinished =
      mappedReqs.length > 0 &&
      mappedReqs.every((r) => isRequisicaoFinalizada(r.status));

    if (exp.status === 'separation' && allReqsFinished) {
      await (supabase as any)
        .from('expedicoes')
        .update({ status: 'loading' })
        .eq('id', exp.id);
      await logExpeditionStatusChange(
        exp.id,
        'loading',
        userProfile?.nome || 'Sistema',
        'Separação automática concluída.',
      );
      exp.status = 'loading';
    }

    const currentRouteOrder = exp.metadata?.route_order || [];
    setRouteOrder(currentRouteOrder);

    setActiveShipment({
      id: exp.id,
      code: exp.code || `EXP-${exp.id.slice(0, 8).toUpperCase()}`,
      vehicle: exp.veiculo || 'N/A',
      driver: exp.motorista || 'N/A',
      status: exp.status as ShipmentStatus,
      progress: calculateProgress(exp.status as ShipmentStatus),
      totalItems: mappedReqs.reduce((acc, r) => acc + r.item_count, 0),
      startTime: exp.start_time,
      estimatedCompletion: exp.end_time || '',
      stops: generateStops(
        mappedReqs,
        exp.status as ShipmentStatus,
        finalLogs,
        currentRouteOrder,
      ),
      requisitionIds: mappedReqs.map((r) => r.id),
    });
    setOpenReqs(mappedReqs);
    setViewMode('tracking');
  };

  const loadActiveExpeditions = async () => {
    await withTrace('logistica.torre_controle.carregar', async () => {
      const startTime = performance.now();
      const activeStatuses = [
        'separation',
        'loading',
        'dispatch',
        'in_transit',
        'unloading',
      ];
      try {
        const { data: activeExps, error } = await (supabase as any)
          .from('expedicoes')
          .select('*, requisicoes(count)')
          .in('status', activeStatuses)
          .order('created_at', { ascending: false });

        const durationMs = Math.round(performance.now() - startTime);
        if (!error && activeExps) {
          setActiveExpeditions(activeExps);
          wideInfo('logistica.torre_controle.carregada', 'Torre de controle carregada com sucesso', enrichWideEvent('logistica', {
            'expedicao.status': activeStatuses.join(','),
            'expedicao.id': activeExps.length > 0 ? activeExps[0].id : '',
            'expedicao.loja_origem': 'fabrica',
            expeditions_count: activeExps.length,
            duration_ms: durationMs,
          }));
          recordOperation('logistica.torre_controle');
          recordOperationDuration('logistica.torre_controle', durationMs);
        } else if (error) {
          wideError('logistica.torre_controle.erro', 'Erro ao carregar torre de controle', enrichWideEvent('logistica', {
            'error.message': error.message,
            'expedicao.status': activeStatuses.join(','),
            'expedicao.loja_origem': 'fabrica',
            'expedicao.id': '',
            duration_ms: durationMs,
          }));
          recordError('logistica_torre_controle', 'carregar');
        }
      } catch (err) {
        const durationMs = Math.round(performance.now() - startTime);
        wideError('logistica.torre_controle.erro', 'Erro inesperado ao carregar torre de controle', enrichWideEvent('logistica', {
          'error.message': err instanceof Error ? err.message : String(err),
          'expedicao.status': activeStatuses.join(','),
          'expedicao.loja_origem': 'fabrica',
          'expedicao.id': '',
          duration_ms: durationMs,
        }));
        recordError('logistica_torre_controle', 'carregar');
      }
      // Não força viewMode='dashboard' — respeita a tab top-level escolhida (drp/dashboard/history).
    }, telemetryAttrs);
  };

  useEffect(() => {
    loadActiveExpeditions();
  }, []);

  const fetchHistory = async () => {
    setLoadingHistory(true);
    let q = (supabase as any)
      .from('expedicoes')
      .select('*')
      .eq('status', 'completed')
      .order('created_at', { ascending: false });
    if (historyFilterDate) q = q.eq('data_agendamento', historyFilterDate);
    const { data } = await q;
    setHistoryList(data || []);
    setLoadingHistory(false);
  };

  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => {
    if (viewMode === 'history') fetchHistory();
  }, [viewMode, historyFilterDate]);

  useEffect(() => {
    if (viewMode === 'creation') {
      const fetch = async () => {
        setLoadingReqs(true);
        const { data } = await (supabase as any)
          .from('requisicoes')
          .select(
            'id, loja_solicitante, data_recebimento, created_at, status, requisicoes_itens(count)',
          )
          .neq('status', 'finalizada')
          .eq('data_recebimento', selectedDate)
          .order('created_at', { ascending: false });

        if (data) {
          setOpenReqs(
            data.map((r: any) => ({
              id: r.id,
              loja_solicitante: r.loja_solicitante,
              data_recebimento: r.data_recebimento,
              created_at: r.created_at,
              status: r.status,
              item_count: r.requisicoes_itens[0]?.count || 0,
            })),
          );
        } else setOpenReqs([]);
        setLoadingReqs(false);
      };
      fetch();
    }
  }, [viewMode, selectedDate]);

  const handleUpdateExpedition = async () => {
    if (!activeShipment || selectedReqs.length === 0) return;
    const newReqs = openReqs.filter((r) => selectedReqs.includes(r.id));
    const storeNames = newReqs.map((r) => r.loja_solicitante).join(', ');

    await (supabase as any)
      .from('requisicoes')
      .update({ expedicao_id: activeShipment.id })
      .in('id', selectedReqs);
    await (supabase as any).from('expedicao_logs').insert({
      expedicao_id: activeShipment.id,
      title: 'Expedição Atualizada',
      description: `Adicionadas ${selectedReqs.length} requisições (${storeNames}).`,
      type: 'info',
      user_name: userProfile?.nome || 'Sistema',
    });

    await loadExpedition(activeShipment.id);
    setSelectedReqs([]);
    setIsEditingExpedition(false);
    setViewMode('tracking');
  };

  const handleStartDispatch = async () => {
    if (!activeShipment) return;
    await withTrace('logistica.expedicao.despachar', async () => {
      const startTime = performance.now();
      try {
        await (supabase as any)
          .from('expedicoes')
          .update({ status: 'dispatch' })
          .eq('id', activeShipment.id);
        await logExpeditionStatusChange(
          activeShipment.id,
          'dispatch',
          userProfile?.nome || 'Sistema',
          `Carregamento concluído. Iniciando conferência.`,
        );
        const durationMs = Math.round(performance.now() - startTime);
        wideInfo('logistica.expedicao.status_alterado', 'Status da expedição alterado para despacho', enrichWideEvent('logistica', {
          'expedicao.id': activeShipment.id,
          'expedicao.status': 'dispatch',
          'expedicao.loja_origem': 'fabrica',
          'expedicao.loja_destino': activeShipment.stops.map((s) => s.store).join(', '),
          'corrida.motorista': activeShipment.driver,
          'expedicao.status_anterior': activeShipment.status,
          'expedicao.status_novo': 'dispatch',
          duration_ms: durationMs,
        }));
        recordOperation('logistica.expedicao');
        await loadExpedition(activeShipment.id);
        toast.success('Carregamento confirmado!');
      } catch (err) {
        wideError('logistica.expedicao.erro', 'Erro ao despachar expedição', enrichWideEvent('logistica', {
          'error.message': err instanceof Error ? err.message : String(err),
          'expedicao.id': activeShipment.id,
          'expedicao.status': activeShipment.status,
          'expedicao.loja_origem': 'fabrica',
          'expedicao.operacao': 'despachar',
        }));
        recordError('logistica_expedicao', 'despachar');
      }
    }, telemetryAttrs);
  };

  const handleCompleteDispatch = async () => {
    if (!activeShipment) return;
    await withTrace('logistica.expedicao.transito', async () => {
      const startTime = performance.now();
      try {
        await (supabase as any)
          .from('expedicoes')
          .update({ status: 'in_transit' })
          .eq('id', activeShipment.id);
        await logExpeditionStatusChange(
          activeShipment.id,
          'in_transit',
          userProfile?.nome || 'Sistema',
          `Despacho autorizado. Em trânsito.`,
        );
        const durationMs = Math.round(performance.now() - startTime);
        wideInfo('logistica.expedicao.status_alterado', 'Expedição despachada e em trânsito', enrichWideEvent('logistica', {
          'expedicao.id': activeShipment.id,
          'expedicao.status': 'in_transit',
          'expedicao.loja_origem': 'fabrica',
          'expedicao.loja_destino': activeShipment.stops.map((s) => s.store).join(', '),
          'corrida.motorista': activeShipment.driver,
          'expedicao.status_anterior': activeShipment.status,
          'expedicao.status_novo': 'in_transit',
          duration_ms: durationMs,
        }));
        recordOperation('logistica.expedicao');
        await loadExpedition(activeShipment.id);
        toast.success('Expedição despachada!');
      } catch (err) {
        wideError('logistica.expedicao.erro', 'Erro ao colocar expedição em trânsito', enrichWideEvent('logistica', {
          'error.message': err instanceof Error ? err.message : String(err),
          'expedicao.id': activeShipment.id,
          'expedicao.status': activeShipment.status,
          'expedicao.loja_origem': 'fabrica',
          'expedicao.operacao': 'transito',
        }));
        recordError('logistica_expedicao', 'transito');
      }
    }, telemetryAttrs);
  };

  const handleDeleteExpedition = async () => {
    if (!activeShipment || !confirm('Excluir expedição?')) return;
    await withTrace('logistica.expedicao.excluir', async () => {
      const startTime = performance.now();
      try {
        await (supabase as any)
          .from('requisicoes')
          .update({ expedicao_id: null, status: 'em_fila' })
          .eq('expedicao_id', activeShipment.id);
        await (supabase as any)
          .from('expedicao_logs')
          .delete()
          .eq('expedicao_id', activeShipment.id);
        await (supabase as any)
          .from('expedicoes')
          .delete()
          .eq('id', activeShipment.id);

        const durationMs = Math.round(performance.now() - startTime);
        wideInfo('logistica.expedicao.excluida', 'Expedição excluída com sucesso', enrichWideEvent('logistica', {
          'expedicao.id': activeShipment.id,
          'expedicao.status': activeShipment.status,
          'expedicao.loja_origem': 'fabrica',
          'expedicao.loja_destino': activeShipment.stops.map((s) => s.store).join(', '),
          'expedicao.code': activeShipment.code,
          duration_ms: durationMs,
        }));
        recordOperation('logistica.expedicao');
        recordOperationDuration('logistica.expedicao', durationMs);

        setActiveShipment(null);
        setViewMode('dashboard');
        loadActiveExpeditions();
        toast.success('Expedição cancelada.');
      } catch (err) {
        wideError('logistica.expedicao.erro', 'Erro ao excluir expedição', enrichWideEvent('logistica', {
          'error.message': err instanceof Error ? err.message : String(err),
          'expedicao.id': activeShipment.id,
          'expedicao.status': activeShipment.status,
          'expedicao.loja_origem': 'fabrica',
          'expedicao.operacao': 'excluir',
        }));
        recordError('logistica_expedicao', 'excluir');
      }
    }, telemetryAttrs);
  };

  const handleCreateExpedition = async () => {
    if (selectedReqs.length === 0) return;
    const selected = openReqs.filter((r) => selectedReqs.includes(r.id));
    const storeNames = selected.map((r) => r.loja_solicitante).join(', ');
    const code = `EXP-${new Date().getFullYear()}-${String(Math.floor(Math.random() * 1000)).padStart(3, '0')}`;

    await withTrace('logistica.expedicao.criar', async () => {
      const startTime = performance.now();
      try {
        const { data: expData } = await (supabase as any)
          .from('expedicoes')
          .insert({
            code,
            status: 'separation',
            data_agendamento: selectedDate,
            start_time: new Date().toISOString(),
          })
          .select()
          .single();

        await (supabase as any)
          .from('requisicoes')
          .update({ expedicao_id: expData.id })
          .in('id', selectedReqs);
        await (supabase as any).from('expedicao_logs').insert({
          expedicao_id: expData.id,
          title: 'Expedição Criada',
          description: `Rota para ${selectedReqs.length} lojas (${storeNames}).`,
          type: 'info',
          user_name: userProfile?.nome || 'Sistema',
        });

        const durationMs = Math.round(performance.now() - startTime);
        wideInfo('logistica.expedicao.criada', 'Nova expedição criada', enrichWideEvent('logistica', {
          'expedicao.id': expData.id,
          'expedicao.status': 'separation',
          'expedicao.loja_origem': 'fabrica',
          'expedicao.loja_destino': storeNames,
          'expedicao.code': code,
          'expedicao.requisicoes_count': selectedReqs.length,
          'expedicao.lojas': storeNames,
          duration_ms: durationMs,
        }));
        recordOperation('logistica.expedicao');
        recordOperationDuration('logistica.expedicao', durationMs);

        loadExpedition(expData.id);
      } catch (err) {
        const durationMs = Math.round(performance.now() - startTime);
        wideError('logistica.expedicao.erro', 'Erro ao criar expedição', enrichWideEvent('logistica', {
          'error.message': err instanceof Error ? err.message : String(err),
          'expedicao.id': '',
          'expedicao.status': 'separation',
          'expedicao.loja_origem': 'fabrica',
          'expedicao.loja_destino': storeNames,
          'expedicao.operacao': 'criar',
          duration_ms: durationMs,
        }));
        recordError('logistica_expedicao', 'criar');
      }
    }, telemetryAttrs);
  };

  const handleSaveRoute = async (newOrder: string[]) => {
    if (!activeShipment) return;
    const { data: currentExp } = await (supabase as any)
      .from('expedicoes')
      .select('metadata')
      .eq('id', activeShipment.id)
      .single();
    await (supabase as any)
      .from('expedicoes')
      .update({ metadata: { ...currentExp?.metadata, route_order: newOrder } })
      .eq('id', activeShipment.id);
    toast.success('Rota atualizada!');
    setRouteOrder(newOrder);
    loadExpedition(activeShipment.id);
  };

  const toggleReqSelection = (id: number) => {
    setSelectedReqs((prev) =>
      prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id],
    );
  };

  const handleExit = () => {
    // Em creation/tracking volta pro overview (dashboard); em top-level tabs sai pra /logistica
    if (viewMode === 'creation' || viewMode === 'tracking') {
      setViewMode('dashboard');
      setActiveShipment(null);
      loadActiveExpeditions();
      return;
    }
    setIsLeaving(true);
    setTimeout(() => navigate('/logistica'), 300);
  };

  /** Bifurcação DRP → Iniciar Expedição: pré-seleciona requisições e troca pra creation. */
  const handleIniciarFromDrp = (reqIds: number[], dataChegada: string) => {
    setSelectedDate(dataChegada);
    setSelectedReqs(reqIds);
    setViewMode('creation');
  };

  /** Bifurcação DRP → Voltar ao menu: navega pra /logistica. */
  const handleVoltarMenuFromDrp = () => {
    setIsLeaving(true);
    setTimeout(() => navigate('/logistica'), 300);
  };

  const handleUpdateVehicle = async () => {
    if (!activeShipment) return;

    const vehicleToSave = newVehicleName.trim() || 'Veículo a definir';

    const { error } = await (supabase as any)
      .from('expedicoes')
      .update({ veiculo: vehicleToSave })
      .eq('id', activeShipment.id);

    if (error) {
      toast.error('Erro ao atualizar veículo');
      return;
    }

    setActiveShipment((prev) =>
      prev ? { ...prev, vehicle: vehicleToSave } : null,
    );
    setIsEditingVehicle(false);
    toast.success('Veículo atualizado!');
  };

  return (
    <div className="min-h-screen bg-[#F5F5F0] text-[#2D362E] font-sans selection:bg-[#57715B]/20 selection:text-[#57715B] overflow-x-hidden relative">
      {/* --- BACKGROUND ELEMENTS --- */}
      {/* Store Awning Stripe Effect (Top Border) */}
      <div className="absolute top-0 left-0 right-0 h-1.5 bg-[repeating-linear-gradient(90deg,#57715B,#57715B_20px,#ffffff_20px,#ffffff_40px)] opacity-80 z-50 pointer-events-none" />

      {/* Animated Plant Background Elements - Pulse */}
      <div
        className="absolute top-[-5%] right-[-10%] w-[300px] h-[300px] opacity-[0.03] pointer-events-none animate-pulse"
        style={{ animationDuration: '10s' }}
      >
        <Leaf className="w-full h-full text-[#57715B] rotate-12" />
      </div>
      <div
        className="absolute bottom-[20%] left-[-15%] w-[400px] h-[400px] opacity-[0.03] pointer-events-none animate-pulse delay-1000"
        style={{ animationDuration: '12s' }}
      >
        <Leaf className="w-full h-full text-[#57715B] -rotate-45" />
      </div>

      {/* Soft Ambient Glows */}
      <div className="absolute top-[20%] left-[10%] w-[200px] h-[200px] bg-[#57715B]/5 rounded-full blur-[80px] pointer-events-none" />
      <div className="absolute bottom-[30%] right-[10%] w-[250px] h-[250px] bg-[#C5A065]/5 rounded-full blur-[80px] pointer-events-none" />

      <main
        className={cn(
          'relative z-10 p-4 md:p-6 lg:p-8 w-full mx-auto transition-all duration-500',
          isLeaving ? 'opacity-0 translate-y-4' : '',
        )}
      >
        {/* --- HEADER --- */}
        <header className="flex flex-col md:flex-row items-start md:items-center justify-between gap-4 mb-8 pt-4">
          <div className="flex items-center gap-3">
            <Button data-mia-action="exit"
              variant="ghost"
              size="icon"
              onClick={handleExit}
              className="rounded-full hover:bg-[#E6DCCF]/50 text-[#57715B] transition-colors h-11 w-11"
            >
              <ArrowLeft className="w-6 h-6" strokeWidth={2.5} />
            </Button>
            <div>
              <div className="flex items-center gap-2">
                <h1 className="text-3xl font-bold tracking-tight text-[#2D362E] font-serif">
                  Torre de Controle
                </h1>
                <Badge
                  variant="secondary"
                  className="hidden md:flex bg-[#57715B] text-[#F5F5F0] hover:bg-[#4A614D] border-none gap-1 rounded-full px-3 py-1 shadow-sm"
                >
                  <Leaf className="w-3 h-3" />
                  Online
                </Badge>
              </div>
              <p className="text-sm text-[#57715B] font-medium opacity-80 mt-1">
                Gestão inteligente de logística e entregas
              </p>
            </div>
          </div>

          <div className="flex items-center gap-3 w-full md:w-auto">
            {viewMode === 'dashboard' && (
              <>
                <Button
                  onClick={() => setViewMode('history')}
                  variant="outline"
                  className="rounded-full border-[#C5A065]/50 text-[#57715B] hover:bg-[#F5F5F0] bg-white/50 backdrop-blur-sm"
                >
                  <History className="w-4 h-4 mr-2" />
                  Histórico
                </Button>
                <Button
                  onClick={() => setViewMode('creation')}
                  className="rounded-full bg-[#57715B] hover:bg-[#4A614D] text-white shadow-lg shadow-[#57715B]/30 border-none"
                >
                  <Plus className="w-4 h-4 mr-2" />
                  Nova Expedição
                </Button>
              </>
            )}
          </div>
        </header>

        {/* --- TOP-LEVEL TABS (esconde em sub-views creation/tracking) --- */}
        {viewMode !== 'creation' && viewMode !== 'tracking' && (
          <nav className="flex flex-wrap gap-2 mb-6 border-b border-[#E6DCCF] pb-2">
            {drpEnabled && (
              <button
                type="button"
                onClick={() => setViewMode('drp')}
                className={cn(
                  'px-4 py-2 rounded-t-xl text-sm font-bold transition-colors',
                  viewMode === 'drp'
                    ? 'bg-white text-[#2D362E] border-b-2 border-[#57715B] shadow-sm'
                    : 'text-[#57715B]/70 hover:text-[#57715B] hover:bg-white/40',
                )}
              >
                Plano de Reposição (DRP)
              </button>
            )}
            <button
              type="button"
              onClick={() => {
                setViewMode('dashboard');
                loadActiveExpeditions();
              }}
              className={cn(
                'px-4 py-2 rounded-t-xl text-sm font-bold transition-colors',
                viewMode === 'dashboard'
                  ? 'bg-white text-[#2D362E] border-b-2 border-[#57715B] shadow-sm'
                  : 'text-[#57715B]/70 hover:text-[#57715B] hover:bg-white/40',
              )}
            >
              Expedições Ativas
            </button>
            <button
              type="button"
              onClick={() => setViewMode('history')}
              className={cn(
                'px-4 py-2 rounded-t-xl text-sm font-bold transition-colors',
                viewMode === 'history'
                  ? 'bg-white text-[#2D362E] border-b-2 border-[#57715B] shadow-sm'
                  : 'text-[#57715B]/70 hover:text-[#57715B] hover:bg-white/40',
              )}
            >
              Histórico
            </button>
          </nav>
        )}

        {/* --- CONTENT AREA --- */}

        {viewMode === 'drp' && drpEnabled && (
          <div className="animate-in fade-in duration-300">
            <DistributionPlanTab
              onIniciarExpedicao={handleIniciarFromDrp}
              onVoltarMenu={handleVoltarMenuFromDrp}
            />
          </div>
        )}

        {viewMode === 'drp' && !drpEnabled && (
          <div className="rounded-2xl bg-amber-50 border border-amber-200 p-6 text-amber-900">
            <h3 className="font-bold">Acesso restrito</h3>
            <p className="text-sm mt-1">
              O Plano de Reposição (DRP) é exclusivo para administradores.
            </p>
          </div>
        )}

        {viewMode === 'dashboard' && (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
            {activeExpeditions.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-24 text-center">
                <div className="w-32 h-32 bg-white/50 rounded-full flex items-center justify-center mb-6 ring-8 ring-[#E6DCCF]/30 backdrop-blur-md shadow-inner">
                  <Truck
                    className="w-14 h-14 text-[#C5A065]"
                    strokeWidth={1.5}
                  />
                </div>
                <h3 className="text-xl font-bold text-[#2D362E] font-serif">
                  Nenhuma expedição ativa
                </h3>
                <p className="text-[#57715B] max-w-sm mt-3 opacity-80">
                  Comece criando uma nova expedição para monitorar as entregas
                  do dia com qualidade Momma.
                </p>
                <Button
                  onClick={() => setViewMode('creation')}
                  className="mt-8 rounded-full bg-[#2D362E] text-[#F5F5F0] hover:bg-black px-8 py-6 text-lg shadow-xl shadow-black/10"
                >
                  Criar Agora
                </Button>
              </div>
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                {activeExpeditions.map((exp) => (
                  <button
                    key={exp.id}
                    onClick={() => loadExpedition(exp.id)}
                    className={cn(
                      'text-left group cursor-pointer transition-all duration-500 hover:-translate-y-2',
                      'relative overflow-hidden rounded-[2rem] p-6 h-full',
                      'bg-white/60', // Airy background
                      'backdrop-blur-xl saturate-150', // Glass effect
                      'border border-white/50', // Subtle border
                      'shadow-[0_8px_32px_-8px_rgba(0,0,0,0.05)]', // Soft shadow
                      'hover:shadow-[0_12px_40px_-12px_rgba(197,160,101,0.25)] hover:border-[#C5A065]/30', // Gold glow on hover
                    )}
                  >
                    <div className="absolute inset-0 bg-gradient-to-br from-white/40 via-transparent to-[#C5A065]/5 pointer-events-none" />

                    <div className="relative z-10">
                      <div className="flex justify-between items-start mb-4">
                        <Badge
                          variant="outline"
                          className="font-mono text-[10px] text-[#57715B] border-[#E6DCCF] bg-[#F5F5F0]"
                        >
                          {exp.code}
                        </Badge>
                        <StatusBadge status={exp.status} />
                      </div>

                      <h3 className="text-xl font-bold text-[#2D362E] mb-1 group-hover:text-[#57715B] transition-colors font-serif truncate">
                        {exp.veiculo || 'Veículo a definir'}
                      </h3>
                      <p className="text-xs text-[#57715B] mb-6 flex items-center gap-1.5 opacity-80">
                        <CalendarDays className="w-3.5 h-3.5" />
                        {new Date(exp.created_at).toLocaleDateString('pt-BR', {
                          weekday: 'long',
                          day: '2-digit',
                          month: 'long',
                        })}
                      </p>

                      <div className="space-y-3">
                        <div className="flex items-center justify-between text-xs font-bold text-[#57715B]">
                          <span className="flex items-center gap-1.5 opacity-80">
                            <Store className="w-3.5 h-3.5" />
                            {exp.requisicoes?.[0]?.count || 0} Lojas
                          </span>
                          <span>{calculateProgress(exp.status)}%</span>
                        </div>
                        <Progress
                          value={calculateProgress(exp.status)}
                          className="h-2 rounded-full bg-[#E6DCCF]"
                        />
                      </div>
                    </div>
                  </button>
                ))}
              </div>
            )}
          </div>
        )}

        {viewMode === 'creation' && (
          <div className="max-w-2xl mx-auto animate-in fade-in slide-in-from-bottom-8 duration-500">
            <Card className="border-white/50 bg-white/80 backdrop-blur-2xl shadow-2xl shadow-[#57715B]/10 rounded-[2.5rem] overflow-hidden">
              <CardHeader className="bg-[#F5F5F0]/50 border-b border-[#E6DCCF] px-10 pt-10 pb-6">
                <div className="flex items-center justify-between">
                  <div>
                    <CardTitle className="text-2xl font-bold text-[#2D362E] font-serif">
                      Nova Expedição
                    </CardTitle>
                    <CardDescription className="text-[#57715B]">
                      Selecione as requisições para a rota de hoje.
                    </CardDescription>
                  </div>
                  <Input data-mia-field="selected_date"
                    type="date"
                    value={selectedDate}
                    onChange={(e) => setSelectedDate(e.target.value)}
                    className="w-auto bg-white border-[#E6DCCF] rounded-xl shadow-sm text-[#57715B]"
                  />
                </div>
              </CardHeader>

              <div className="px-10 py-5 bg-white border-b border-[#F5F5F0] sticky top-0 z-10 flex items-center gap-4">
                <Search className="w-5 h-5 text-[#C5A065]" />
                <Input data-mia-field="new_vehicle_name"
                  placeholder="Filtrar lojas..."
                  className="border-none shadow-none focus-visible:ring-0 px-0 text-base bg-transparent placeholder:text-[#57715B]/40 text-[#57715B]"
                />
                <Badge
                  variant="secondary"
                  className="ml-auto bg-[#57715B] text-white px-3 py-1 rounded-full"
                >
                  {selectedReqs.length} selecionados
                </Badge>
              </div>

              <ScrollArea className="h-[400px] bg-white/50">
                {loadingReqs ? (
                  <div className="flex justify-center p-12">
                    <Loader2 className="w-8 h-8 animate-spin text-[#57715B]" />
                  </div>
                ) : openReqs.length === 0 ? (
                  <div className="flex flex-col items-center justify-center py-20 text-[#57715B] px-6 text-center opacity-50">
                    <ClipboardList
                      className="w-16 h-16 mb-4 opacity-20"
                      strokeWidth={1}
                    />
                    <p>Nenhuma requisição pendente para esta data.</p>
                  </div>
                ) : (
                  <div className="divide-y divide-[#F5F5F0]">
                    {openReqs.map((req) => (
                      <div
                        key={req.id}
                        onClick={() => toggleReqSelection(req.id)}
                        className={cn(
                          'px-10 py-5 flex items-center gap-5 cursor-pointer hover:bg-[#F5F5F0]/50 transition-colors',
                          selectedReqs.includes(req.id) ? 'bg-[#57715B]/5' : '',
                        )}
                      >
                        <Checkbox
                          checked={selectedReqs.includes(req.id)}
                          className="border-[#C5A065] data-[state=checked]:bg-[#57715B] data-[state=checked]:border-[#57715B] w-5 h-5 rounded-md"
                        />
                        <div className="flex-1">
                          <div className="flex justify-between items-center mb-1">
                            <span className="font-bold text-[#2D362E] text-base">
                              {req.loja_solicitante}
                            </span>
                            <span className="text-[10px] font-mono text-[#57715B]/60 bg-[#F5F5F0] px-2 py-1 rounded-md">
                              #{req.id}
                            </span>
                          </div>
                          <div className="flex items-center gap-3 text-xs text-[#57715B] opacity-80">
                            <span className="flex items-center gap-1 font-medium">
                              <Package className="w-3.5 h-3.5" />{' '}
                              {req.item_count} itens
                            </span>
                            <span className="w-1 h-1 rounded-full bg-[#C5A065]" />
                            <span>
                              {new Date(req.created_at).toLocaleTimeString(
                                'pt-BR',
                                { hour: '2-digit', minute: '2-digit' },
                              )}
                            </span>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </ScrollArea>

              <div className="p-8 bg-[#F5F5F0]/50 border-t border-[#E6DCCF] flex justify-end gap-3">
                <Button
                  variant="ghost"
                  onClick={() => {
                    setIsEditingExpedition(false);
                    setViewMode('dashboard');
                    setSelectedReqs([]);
                  }}
                  className="text-[#57715B] hover:bg-[#E6DCCF]/50 rounded-xl"
                >
                  Cancelar
                </Button>
                <Button
                  onClick={
                    isEditingExpedition
                      ? handleUpdateExpedition
                      : handleCreateExpedition
                  }
                  disabled={selectedReqs.length === 0}
                  className="rounded-full bg-[#57715B] hover:bg-[#4A614D] text-white shadow-xl shadow-[#57715B]/20 px-8 py-6 text-base font-bold transition-transform active:scale-95"
                >
                  {isEditingExpedition
                    ? 'Salvar Alterações'
                    : 'Iniciar Expedição'}
                </Button>
              </div>
            </Card>
          </div>
        )}

        {viewMode === 'tracking' && activeShipment && (
          <div className="grid grid-cols-1 xl:grid-cols-3 gap-8 animate-in fade-in slide-in-from-bottom-8 duration-700">
            {/* LEFT: STATUS & TIMELINE */}
            <div className="xl:col-span-2 space-y-8">
              {/* Main Status Cards */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {/* Current Status Card */}
                <Card className="border-0 bg-gradient-to-br from-[#2D362E] to-[#1A201B] text-[#F5F5F0] rounded-[2.5rem] shadow-2xl shadow-black/20 relative overflow-hidden h-[300px] flex flex-col justify-between p-10">
