                        <Loader2 className="w-5 h-5 animate-spin text-[#C5A065]" />
                        <span className="font-medium tracking-wide">
                          Aguardando separações...
                        </span>
                      </div>
                    )}
                  </div>
                </Card>

                {/* Route Stats Card */}
