                            .filter((s) => {
                              const tipo = String(s.tipo || '').toLowerCase();
                              const nome = String(s.name || '').toLowerCase();
                              const isFactoryByTipo =
                                tipo === 'fabrica' || tipo === 'factory';
                              const isFactoryByName =
                                nome.includes('fábrica') ||
                                nome.includes('fabrica');
                              return !isFactoryByTipo && !isFactoryByName;
                            })
                            .map((s) => (
                              <SelectItem key={s.id} value={String(s.id)}>
                                {s.name}
                              </SelectItem>
                            ))}
                        </SelectContent>
                      </Select>
                    </div>
                    <div className="flex gap-2 pt-2">
                      <Button
                        data-mia-action="limpar-filtros"
                        variant="ghost"
                        size="sm"
                        className="flex-1"
                        onClick={() => {
                          setLojaFilter('todas');
                          setStatusFilter(['em_fila', 'em_progresso']);
                        }}
                      >
                        Limpar
                      </Button>
                      <Button data-mia-action="fetch-queue"
                        size="sm"
                        className="flex-1 bg-[#57715B] hover:bg-[#57715B]/90 text-white"
                        onClick={fetchQueue}
                      >
                        Aplicar
                      </Button>
                    </div>
                  </div>
                </PopoverContent>
              </Popover>
              <Button
                variant="outline"
                size="sm"
                onClick={() => setShowReportsModal(true)}
                className="h-11 rounded-xl bg-white/85 dark:bg-zinc-900/60 backdrop-blur-xl border-zinc-200/80 dark:border-white/10 hover:bg-white hover:border-[#57715B]/40 text-sm font-medium tablet:h-12"
              >
                <ClipboardList className="w-4 h-4 mr-2 tablet:w-5 tablet:h-5" />
                Relatórios
              </Button>
              {/* Em tablet, Torre entra na mesma linha (3-col grid). Em mobile, fica abaixo. */}
              {isTablet && (
                <Button
                  onClick={() => navigate('/requisicao')}
                  className="h-12 rounded-xl bg-gradient-to-r from-[#57715B] to-emerald-600 hover:from-[#4a6250] hover:to-emerald-700 text-white shadow-md shadow-[#57715B]/20 text-sm font-semibold"
                >
                  <Plus className="w-5 h-5 mr-2" />
                  Criar nova requisição
                </Button>
              )}
            </div>

            {/* Torre fora do grid — só em mobile portrait/phone (em tablet ela já entrou no grid acima). */}
            {!isTablet && (
              <Button
                onClick={() => navigate('/requisicao')}
                className="w-full h-11 rounded-xl bg-gradient-to-r from-[#57715B] to-emerald-600 hover:from-[#4a6250] hover:to-emerald-700 text-white shadow-md shadow-[#57715B]/20 text-sm font-semibold"
              >
                <Plus className="w-4 h-4 mr-2" />
                Criar nova requisição
              </Button>
            )}

            {/* Navegação semanal (só no modo kanban) */}
            {viewMode === 'kanban' && (
              <div className="grid grid-cols-3 gap-2">
                <Button
                  variant="outline"
                  size="sm"
                  className="h-10 rounded-xl text-[11px] bg-white/85 dark:bg-zinc-900/60 backdrop-blur-xl border-zinc-200/80 dark:border-white/10"
                  onClick={() => {
                    prependMoreDays(7);
                    requestAnimationFrame(() => {
                      const el = scrollRef.current;
                      if (el) el.scrollLeft = 0;
                    });
                  }}
                >
                  ← Anterior
                </Button>
                <Button
                  variant="outline"
                  size="sm"
                  className="h-10 rounded-xl text-[11px] font-bold bg-[#57715B]/10 border-[#57715B]/30 text-[#57715B] hover:bg-[#57715B]/20"
                  onClick={() => {
                    const target = document.getElementById(`day-col-${todayISO}`);
                    if (target) target.scrollIntoView({ behavior: 'smooth', inline: 'start' });
                  }}
                >
                  Hoje
                </Button>
                <Button
                  variant="outline"
                  size="sm"
                  className="h-10 rounded-xl text-[11px] bg-white/85 dark:bg-zinc-900/60 backdrop-blur-xl border-zinc-200/80 dark:border-white/10"
                  onClick={() => {
                    appendMoreDays(7);
                    requestAnimationFrame(() => {
                      const el = scrollRef.current;
                      if (el) el.scrollLeft = el.scrollWidth;
                    });
                  }}
                >
                  Próxima →
                </Button>
              </div>
            )}
          </div>
        ) : (
          <div className="mb-6 flex items-center justify-between gap-4 flex-wrap">
            {/* Hero desktop: icon container + title + meta */}
            <div className="flex items-center gap-4 min-w-0">
              <div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-gradient-to-br from-[#57715B] to-[#4a6250] shadow-lg shadow-[#57715B]/20 flex-shrink-0">
                <ClipboardList className="h-6 w-6 text-white" />
              </div>
              <div className="min-w-0">
                <h1 className="text-2xl lg:text-3xl font-bold tracking-tight text-foreground">
                  Logística
                </h1>
                <p className="text-sm text-muted-foreground">
                  <span className="font-semibold text-foreground">{requisicoes.length}</span> requisições
                  <span className="mx-1.5 text-muted-foreground/40">·</span>
                  Fila, quadro e analytics em tempo real
                </p>
              </div>
            </div>

            <div className="flex items-center gap-2 flex-wrap">
              {/* View mode toggle */}
              <div className="rounded-xl border border-zinc-200/80 dark:border-white/10 bg-white/85 dark:bg-zinc-900/60 backdrop-blur-xl shadow-[0_1px_3px_rgba(0,0,0,0.04)] p-1">
                <ToggleGroup
                  type="single"
                  value={viewMode}
                  onValueChange={(v) => v && setViewMode(v as any)}
                  className="gap-0.5"
                >
                  <ToggleGroupItem
                    value="kanban"
                    className="h-9 px-3 rounded-lg text-xs data-[state=on]:bg-[#57715B] data-[state=on]:text-white data-[state=on]:shadow-sm"
                  >
                    <KanbanSquare className="w-4 h-4 mr-1.5" />
                    Quadro
                  </ToggleGroupItem>
                  <ToggleGroupItem
                    value="lista"
                    className="h-9 px-3 rounded-lg text-xs data-[state=on]:bg-[#57715B] data-[state=on]:text-white data-[state=on]:shadow-sm"
                  >
                    <List className="w-4 h-4 mr-1.5" />
                    Lista
                  </ToggleGroupItem>
                  <ToggleGroupItem
                    value="analytics"
                    className="h-9 px-3 rounded-lg text-xs data-[state=on]:bg-[#57715B] data-[state=on]:text-white data-[state=on]:shadow-sm"
                  >
                    <BarChart3 className="w-4 h-4 mr-1.5" />
                    Analytics
                  </ToggleGroupItem>
                </ToggleGroup>
              </div>

              {viewMode === 'kanban' && (
                <div className="flex items-center gap-1 rounded-xl border border-zinc-200/80 dark:border-white/10 bg-white/85 dark:bg-zinc-900/60 backdrop-blur-xl shadow-[0_1px_3px_rgba(0,0,0,0.04)] p-1">
                  <Button
                    variant="ghost"
                    size="sm"
                    className="h-9 px-3 rounded-lg text-xs text-muted-foreground hover:text-[#57715B] hover:bg-[#57715B]/10"
                    onClick={() => {
                      prependMoreDays(7);
                      requestAnimationFrame(() => {
                        const el = scrollRef.current;
                        if (el) el.scrollLeft = 0;
                      });
                    }}
                  >
                    ← Semana
                  </Button>
                  <Button
                    variant="ghost"
                    size="sm"
                    className="h-9 px-3 rounded-lg text-xs font-bold bg-[#57715B]/10 text-[#57715B] hover:bg-[#57715B]/20"
                    onClick={() => {
                      const target = document.getElementById(`day-col-${todayISO}`);
                      if (target) target.scrollIntoView({ behavior: 'smooth', inline: 'start' });
                    }}
                  >
                    Hoje
                  </Button>
                  <Button
                    variant="ghost"
                    size="sm"
                    className="h-9 px-3 rounded-lg text-xs text-muted-foreground hover:text-[#57715B] hover:bg-[#57715B]/10"
                    onClick={() => {
                      appendMoreDays(7);
                      requestAnimationFrame(() => {
                        const el = scrollRef.current;
                        if (el) el.scrollLeft = el.scrollWidth;
                      });
                    }}
                  >
                    Semana →
                  </Button>
                </div>
              )}

              <Popover>
                <PopoverTrigger asChild>
                  <Button
                    variant="outline"
                    size="sm"
                    className="rounded-xl h-10 bg-white/85 dark:bg-zinc-900/60 backdrop-blur-xl border-zinc-200/80 dark:border-white/10 hover:bg-white hover:border-[#57715B]/40 shadow-sm"
                  >
                    <Filter className="w-4 h-4 mr-2" /> Filtros
                  </Button>
                </PopoverTrigger>
                <PopoverContent className="w-80 p-4 rounded-xl border-zinc-200/80 bg-white/95 dark:bg-zinc-900/90 backdrop-blur-xl shadow-[0_4px_24px_rgba(0,0,0,0.08)]">
                  <div className="space-y-4">
                    <div>
                      <Label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                        Status
                      </Label>
                      <ToggleGroup
                        type="multiple"
                        value={statusFilter as any}
                        onValueChange={(v) => setStatusFilter(v as any)}
                        className="mt-2 grid grid-cols-3 gap-1"
                      >
                        <ToggleGroupItem value="em_fila" className="text-xs h-9 rounded-lg">
                          Na Fila
                        </ToggleGroupItem>
                        <ToggleGroupItem value="em_progresso" className="text-xs h-9 rounded-lg">
                          Progresso
                        </ToggleGroupItem>
                        <ToggleGroupItem value="finalizada" className="text-xs h-9 rounded-lg">
                          Finalizada
                        </ToggleGroupItem>
                      </ToggleGroup>
                    </div>
                    <div>
                      <Label className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                        Loja
                      </Label>
                      <Select value={lojaFilter} onValueChange={setLojaFilter}>
                        <SelectTrigger data-mia-filter="loja_filter" className="h-10 mt-2 rounded-lg">
                          <SelectValue placeholder="Selecionar loja" />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="todas">Todas</SelectItem>
                          {stores
                            .filter((s) => {
                              const tipo = String(s.tipo || '').toLowerCase();
                              const nome = String(s.name || '').toLowerCase();
                              const isFactoryByTipo =
                                tipo === 'fabrica' || tipo === 'factory';
                              const isFactoryByName =
                                nome.includes('fábrica') ||
                                nome.includes('fabrica');
                              return !isFactoryByTipo && !isFactoryByName;
                            })
                            .map((s) => (
                              <SelectItem key={s.id} value={String(s.id)}>
                                {s.name}
                              </SelectItem>
                            ))}
                        </SelectContent>
                      </Select>
                    </div>
                    <div className="flex gap-2 pt-2">
                      <Button
                        data-mia-action="limpar-filtros"
                        variant="ghost"
                        size="sm"
                        className="flex-1"
                        onClick={() => {
                          setLojaFilter('todas');
                          setStatusFilter(['em_fila', 'em_progresso']);
                        }}
                      >
                        Limpar
                      </Button>
                      <Button data-mia-action="fetch-queue"
                        size="sm"
                        className="flex-1 bg-[#57715B] hover:bg-[#57715B]/90 text-white"
                        onClick={fetchQueue}
                      >
                        Aplicar
                      </Button>
                    </div>
                  </div>
                </PopoverContent>
              </Popover>
              <Button
                variant="outline"
                size="sm"
                onClick={() => setShowReportsModal(true)}
                className="h-10 rounded-xl bg-white/85 dark:bg-zinc-900/60 backdrop-blur-xl border-zinc-200/80 dark:border-white/10 hover:bg-white hover:border-[#57715B]/40 shadow-sm text-sm"
              >
                <ClipboardList className="w-4 h-4 mr-2" />
                Relatórios
              </Button>
              <Button
                size="sm"
                onClick={() => navigate('/requisicao')}
                className="h-10 rounded-xl text-sm bg-gradient-to-r from-[#57715B] to-emerald-600 hover:from-[#4a6250] hover:to-emerald-700 text-white shadow-md shadow-[#57715B]/20 font-semibold"
              >
                <Plus className="w-4 h-4 mr-2" />
                Criar nova requisição
              </Button>
            </div>
          </div>
        )}

        {viewMode === 'analytics' ? (
          <LogisticsAnalyticsDashboard
            requisicoes={requisicoes}
            stores={stores}
          />
        ) : viewMode === 'kanban' ? (
          <DndContext
            sensors={sensors}
            onDragStart={onDragStart}
            onDragEnd={onDragEnd}
            onDragCancel={onDragCancel}
          >
            <div className="relative">
              <div
                ref={scrollRef}
                className="overflow-x-auto scroll-smooth relative z-0 pb-2 custom-scrollbar"
              >
                <div className={classNames('flex items-stretch', isMobile ? 'gap-3' : 'gap-4')}>
                  {weekDays.map((d) => (
                    <div
                      key={d.dateISO}
                      id={`day-col-${d.dateISO}`}
                      data-date-iso={d.dateISO}
                      className={classNames(
                        'shrink-0',
                        isMobile ? 'min-w-[280px] max-w-[280px]' : 'min-w-[320px] max-w-[320px]',
                      )}
                    >
                      <DayColumn
                        day={d}
                        loading={loading}
                        onPrint={() => printDayOrders(d.dateISO, d.label)}
                        isMobile={isMobile}
                        isToday={d.dateISO === todayISO}
                        itemCount={grouped[d.dateISO]?.length || 0}
                      >
                        {grouped[d.dateISO].length === 0 && !loading && (
                          <div className="flex flex-col items-center justify-center py-8 gap-2 text-muted-foreground/60">
                            <Package className="w-8 h-8 opacity-40" />
                            <p className="text-xs italic">Nenhum pedido</p>
                          </div>
                        )}
                        {grouped[d.dateISO].map((r) => (
                          <DraggableReq
                            key={r.id}
                            req={r}
                            displayDateISO={d.dateISO}
                            onClick={() => openDetails(r)}
                            factoryName={factoryName}
                            isMobile={isMobile}
                          />
                        ))}
                      </DayColumn>
                    </div>
                  ))}
                </div>
              </div>
            </div>
            <DragOverlay dropAnimation={dropAnimation} zIndex={10000}>
              {activeId
                ? (() => {
                    const ord = orderById.get(activeId!);
                    return ord ? (
                      <div className="rotate-2 scale-105">
                        <ReqCard
                          req={ord}
                          onClick={() => {}}
                          factoryName={factoryName}
                          isMobile={isMobile}
                        />
                      </div>
                    ) : null;
                  })()
                : null}
            </DragOverlay>
          </DndContext>
        ) : (
          <div className="space-y-4">
            {weekDays.map((day) => {
              const items = grouped[day.dateISO] || [];
              const isTodayCol = day.dateISO === todayISO;
              return (
                <div
                  key={day.key}
                  className={classNames(
                    'relative rounded-2xl border overflow-hidden transition-all duration-300',
                    'bg-white/85 dark:bg-zinc-900/60 backdrop-blur-xl',
                    isTodayCol
                      ? 'border-[#57715B]/50 shadow-[0_0_0_1px_rgba(87,113,91,0.15),0_8px_30px_rgba(87,113,91,0.12)]'
                      : 'border-zinc-200/80 dark:border-white/10 shadow-[0_1px_3px_rgba(0,0,0,0.04),0_4px_16px_rgba(0,0,0,0.04)]',
                  )}
                >
                  {/* Soft gradient overlay */}
                  <div className="absolute inset-0 bg-gradient-to-br from-white/30 via-transparent to-zinc-100/30 dark:from-white/5 dark:to-black/20 pointer-events-none" />

                  <div className="relative z-10 p-4 md:p-5">
                    <div className="flex items-center justify-between gap-2 mb-3">
                      <div className="flex items-center gap-2 min-w-0">
                        {isTodayCol && (
                          <span className="inline-flex h-2 w-2 rounded-full bg-[#57715B] animate-pulse flex-shrink-0" />
                        )}
                        <button
                          onClick={() => printDayOrders(day.dateISO, day.label)}
                          className={classNames(
                            'text-sm font-bold hover:underline underline-offset-4 truncate',
                            isTodayCol ? 'text-[#57715B] dark:text-emerald-400' : 'text-foreground',
                          )}
                        >
                          {day.label}
                        </button>
                        <span className="inline-flex items-center justify-center min-w-[24px] h-6 px-2 rounded-full bg-[#57715B]/10 text-[#57715B] dark:bg-emerald-900/30 dark:text-emerald-400 text-[10px] font-bold flex-shrink-0">
                          {items.length}
                        </span>
                      </div>
                      <Button
                        variant="ghost"
                        size="sm"
                        className="rounded-full h-8 w-8 p-0 text-muted-foreground hover:text-[#57715B] hover:bg-[#57715B]/10 flex-shrink-0"
                        onClick={() => printDayOrders(day.dateISO, day.label)}
                        aria-label="Imprimir dia"
                      >
                        <Printer className="w-3.5 h-3.5" />
                      </Button>
                    </div>
                    <div className={classNames('grid gap-2', isMobile ? 'grid-cols-1' : 'grid-cols-1 md:grid-cols-2 xl:grid-cols-3')}>
                      {loading && items.length === 0 ? (
                        <div className="h-24 rounded-xl animate-pulse bg-white/40 dark:bg-zinc-800/40 border border-white/30 dark:border-white/5" />
                      ) : items.length === 0 ? (
                        <div className="col-span-full flex flex-col items-center justify-center py-6 gap-2 text-muted-foreground/60">
                          <Package className="w-6 h-6 opacity-40" />
                          <p className="text-xs italic">Nenhum pedido neste dia</p>
                        </div>
                      ) : (
                        items.map((req) => (
                          <ReqCard
                            key={`${req.id}-${day.dateISO}`}
                            req={req}
                            displayDateISO={day.dateISO}
                            onClick={() => openDetails(req)}
                            factoryName={factoryName}
                            isMobile={isMobile}
                          />
                        ))
                      )}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}

        <ReportsModal
          isOpen={showReportsModal}
          onClose={() => setShowReportsModal(false)}
        />

        <LogisticsOrderModal
          isOpen={!!selectedReqId}
          onClose={() => setSelectedReqId(null)}
          requisicao={selectedReq}
          onUpdate={fetchQueue}
        />
        </div>
      </div>
    </PermissionBlur>
  );
}

