import { useState, useEffect, useRef, useMemo } from "react";
import { printHTML } from '@/shared/lib/print';
import { Upload, Calculator, Sparkles, FileSpreadsheet, Loader2, Bot, CheckCircle2, ArrowRight, ArrowLeft, Zap, FileCheck, Printer, Trash2, Edit3, Plus, GripVertical, BarChart3, CheckCircle, Users, LogOut, ClipboardList, Store, Clock, Calendar, AlertTriangle } from "lucide-react";
import { useNavigate, useLocation } from "react-router-dom";
import {
  DndContext,
  closestCenter,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  DragEndEvent,
  DragStartEvent,
  DragOverlay,
} from '@dnd-kit/core';
import {
  arrayMove,
  SortableContext,
  sortableKeyboardCoordinates,
  verticalListSortingStrategy,
} from '@dnd-kit/sortable';
import {
  useSortable,
} from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { Progress } from "@/shared/ui/progress";
import { FormErrorBoundary } from "@/shared/ui/FormErrorBoundary";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/shared/ui/card";
import { Button } from "@/shared/ui/button";
import { Textarea } from "@/shared/ui/textarea";
import { Input } from "@/shared/ui/input";
import { Label } from "@/shared/ui/label";
import { Badge } from "@/shared/ui/badge";
import { Separator } from "@/shared/ui/separator";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/shared/ui/tabs";
import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from "@/shared/ui/accordion";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/shared/ui/dialog";
import { StoreSelector, normalizeStoreName, getStoreLabel } from "@/components/stores/StoreSelector";
import { toast } from "sonner";
import { supabase } from "@/integrations/supabase/client";
import { ReportsModal } from "@/features/notas-fiscais/ui/ReportsModal";
import { ReasoningDisplay } from "@/components/ReasoningDisplay";
import { useAuth } from "@/shared/hooks/useAuth";

import { bestCatalogMatch, shouldAutoLock } from "@/shared/lib/productMatch";
import { detectCategory, getEffectiveCategory, shouldPreserveCategory } from "@/shared/lib/category";
import { CategorySelector } from "@/features/requisicoes/ui/CategorySelector";
import { AutoRequisitionWizard } from "@/features/requisicoes/ui/AutoRequisitionWizard";
import { parseDateFromTitle, coerceISODateString, formatDateDDMMYY, getCurrentLocalDate, getTomorrowLocalDate, validateDeliveryDate, cn } from "@/shared/lib/utils";
import { useDebouncedCallback } from "@/shared/hooks/useDebounce";
import { useIsMobile, useIsTablet } from "@/shared/hooks/use-mobile";
import { usePermissions } from "@/shared/hooks/usePermissions";
import { useStore } from "@/shared/contexts/StoreContext";
import { PermissionBlur } from "@/shared/ui/PermissionBlur";
import { calculateContextAndCallAI } from "@/lib/ai/stockCalculator";
import { useMiaRequisicaoActions } from '@/features/mia/model/hooks';
import salesDataRaw from '../data/sales_history.json';
import { handleError } from '@/shared/lib/error-handler';
import { wideDebug, wideInfo, wideWarn, wideError } from '@/shared/lib/telemetry/wide-events';


// AIProcessedItem importado de SortableItem.tsx

interface ActiveSeparation {
  id: string;
  requester_name: string;
  preparer_name: string;
  store_requester: string;
  store_preparer: string;
  order_date: string;
  received_date: string;
  status: string;
