  // Categorias customizadas (para permitir colunas vazias e edição de nomes)
  const [customCategories, setCustomCategories] = useState<string[]>([]);
  const [editingCategory, setEditingCategory] = useState<string | null>(null);
  const [editingCategoryValue, setEditingCategoryValue] = useState<string>('');

  const handleAddCustomCategory = (category: string) => {
    const name = (category || '').trim();
    if (!name) return;
    setCustomCategories(prev => Array.from(new Set([...prev, name])));
    toast.success(`Categoria "${name}" criada`);
  };

  const addCustomCategory = (name?: string) => {
    const base = (name || 'Nova Categoria').trim();
    if (!base) return;
    setCustomCategories(prev => Array.from(new Set([...prev, base])));
    setEditingCategory(base);
    setEditingCategoryValue(base);
    toast.success('Nova categoria criada');
  };

  const renameCategory = async (oldName: string, newName: string) => {
    const oldTrim = (oldName || '').trim();
    const newTrim = (newName || '').trim();
    if (!newTrim) {
      setEditingCategory(null);
      setEditingCategoryValue('');
      return;
    }
    if (oldTrim === newTrim) {
      setEditingCategory(null);
      setEditingCategoryValue('');
      return;
    }

    // Atualizar lista de categorias customizadas
    setCustomCategories(prev => Array.from(new Set(prev.map(c => (c === oldTrim ? newTrim : c)))));

    // Atualizar itens que pertencem à categoria renomeada
    const itemsToUpdateIds: string[] = [];
    setAllItems(prev => prev.map(i => {
      const cat = (i.category?.trim() || 'Geral');
      const man = (i.manualCategory || '').trim();
      if (cat === oldTrim || man === oldTrim) {
        itemsToUpdateIds.push(i.id);
        return { ...i, category: newTrim, manualCategory: newTrim };
      }
      return i;
    }));

    // Sincronizar na sessão ativa, se aplicável
    if (isSessionMode && currentSessionId && itemsToUpdateIds.length) {
      await Promise.allSettled(itemsToUpdateIds.map(id => updateSessionItem(id, { category: newTrim })));
    }

    // Sincronizar com o banco de dados se a requisição foi enviada
    if (currentRequisicaoId && itemsToUpdateIds.length > 0) {
      const numericIds = itemsToUpdateIds.map(id => Number(id)).filter(id => !Number.isNaN(id));
      if (numericIds.length > 0) {
        (supabase as any)
          .from('requisicoes_itens')
          .update({ category: newTrim })
          .in('id', numericIds)
          .then(({ error }) => {
            if (error) {
              handleError(error, { domain: 'requisicoes', operation: 'renomearCategoria', showToast: false });
              toast.error('Erro ao salvar renomeação de categoria');
            }
          });
      }
    }

    setEditingCategory(null);
    setEditingCategoryValue('');
    toast.success(`Categoria renomeada para "${newTrim}"`);
  };

  const removeCustomCategory = (name: string) => {
    const trimmed = (name || '').trim();
    if (!trimmed) return;
    // Verificar se categoria possui itens
    const hasItems = allItems.some(i => {
      const cat = (i.category?.trim() || 'Geral');
      const man = (i.manualCategory || '').trim();
      return cat === trimmed || man === trimmed;
    });
    if (hasItems) {
      toast.error('Não é possível deletar uma categoria com itens');
      return;
    }
    setCustomCategories(prev => prev.filter(c => c !== trimmed));
    if (editingCategory === trimmed) {
      setEditingCategory(null);
      setEditingCategoryValue('');
    }
    toast.success(`Categoria "${trimmed}" deletada`);
  };

  // Formatação consistente em padrão brasileiro (dd/MM/yyyy HH:mm), timezone São Paulo
  const formatDateTimeBr = (value?: string | null) => {
    if (!value) return '';
    const d = new Date(value);
    if (isNaN(d.getTime())) return '';
    return new Intl.DateTimeFormat('pt-BR', {
      day: '2-digit', month: '2-digit', year: 'numeric',
      hour: '2-digit', minute: '2-digit', hour12: false,
      timeZone: 'America/Sao_Paulo'
    }).format(d);
  };

  const getQueueTimestamp = (req: any) => {
    const v = req?.enqueued_at ?? req?.enqueuedAt ?? req?.created_at ?? req?.createdAt ?? null;
    return formatDateTimeBr(v) || '—';
  };

  // Função para gerar ID único
  const generateId = () => Math.random().toString(36).substr(2, 9);

  // Estado para controlar a sincronização em tempo real
  const [realtimeChannel, setRealtimeChannel] = useState<any>(null);

  // Estados para sessões ativas
  const [isSessionMode, setIsSessionMode] = useState(false);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);

  // Hooks de sessão ativa
  const currentSession: any = null;
  const sessionItems: any[] = [];
  const sessionLoading = false;
  const createSession = async (..._args: any[]) => null as any;
  const loadSession = async (..._args: any[]) => false as boolean;
  const updateSession = async (..._args: any[]) => false as boolean;
  const updateSessionItem = async (..._args: any[]) => false as boolean;
  const addSessionItem = async (..._args: any[]) => null as any;
  const removeSessionItem = async (..._args: any[]) => false as boolean;
  const finalizeSession = async (..._args: any[]) => false as boolean;
  const getItemsAsAIProcessed = () => [] as any[];

  const filteredSavedLists = useMemo(() => {
    if (historyFilter === 'all') return savedLists;
    return savedLists.filter((l: any) => (l.status || 'pendente') === historyFilter);
  }, [savedLists, historyFilter]);

  // Hook otimizado para sincronização
  const syncItem = async (..._args: any[]) => { };
  const clearSyncCache = () => { };

  // Callbacks para realtime
  const handleSessionUpdate = (session: ActiveSessionData) => {
    // Atualizar dados da sessão se necessário
    wideDebug('requisicao.sessao_atualizada', 'Sessao atualizada em tempo real', { domain: 'requisicoes', attributes: { sessionId: session.session_id, status: session.status } });

    // Se a sessão foi finalizada ou removida, limpar estado local
    if (session.status === 'completed' || session.status === 'deleted') {
      wideDebug('requisicao.sessao_finalizada', 'Sessao finalizada/removida, limpando estado local', { domain: 'requisicoes' });
      setIsSessionMode(false);
      setCurrentSessionId(null);
      setAllItems([]);
      // Também sair da sessão no contexto global se ainda estivermos nela
      if (isInSession && globalSessionId === session.session_id) {
        exitSession();
      }
    }

    // Se a sessão ainda está ativa mas não estamos mais nela no contexto global,
    // atualizar estado local para refletir isso
    if (!isInSession && isSessionMode && currentSessionId === session.session_id) {
      wideDebug('requisicao.sessao_desconectada', 'Nao estamos mais na sessao, atualizando estado local', { domain: 'requisicoes' });
      setIsSessionMode(false);
      setCurrentSessionId(null);
    }
  };

  const handleItemUpdate = (item: ActiveSessionItem) => {
    // Atualizar item na lista local usando id como identificador estável
    setAllItems(prev =>
      prev.map(localItem =>
        localItem.id === item.id
          ? {
            ...localItem,
            name: editingNameIdsRef.current.has(item.id) ? localItem.name : item.item_name,
            requested: item.requested_quantity,
            sent: editingQuantityIdsRef.current.has(item.id) ? localItem.sent : item.sent_quantity,
            observation: editingObservationIdsRef.current.has(item.id) ? localItem.observation : item.observation,
            is_separated: item.is_separated,
            separated_by: item.separated_by,
            category: item.category ?? localItem.category ?? detectCategory(item.item_name)
          }
          : localItem
      )
    );
    wideDebug('requisicao.item_atualizado_realtime', 'Item atualizado via realtime', { domain: 'requisicoes', attributes: { itemName: item.item_name } });
  };

  const handleItemInsert = (item: ActiveSessionItem) => {
    // Evitar inserir duplicado caso já exista
    setAllItems(prev => {
      const existingIndex = prev.findIndex(i => i.id === item.id);
      const payloadName = editingNameIdsRef.current.has(item.id) ? prev[existingIndex]?.name : item.item_name;
      const payloadSent = editingQuantityIdsRef.current.has(item.id) ? prev[existingIndex]?.sent : item.sent_quantity;
      const payloadObs = editingObservationIdsRef.current.has(item.id) ? prev[existingIndex]?.observation : item.observation;
      if (existingIndex !== -1) {
        const updated = [...prev];
        updated[existingIndex] = {
          ...updated[existingIndex],
          name: payloadName ?? updated[existingIndex].name,
          requested: item.requested_quantity,
          sent: payloadSent ?? updated[existingIndex].sent,
          observation: payloadObs ?? updated[existingIndex].observation,
          is_separated: item.is_separated,
          separated_by: item.separated_by,
          category: item.category ?? updated[existingIndex].category ?? detectCategory(payloadName ?? item.item_name)
        };
        return updated;
      }
      const newItem: AIProcessedItem = {
        id: item.id,
        name: payloadName ?? item.item_name,
        requested: item.requested_quantity,
        sent: item.sent_quantity,
        observation: item.observation,
        is_separated: item.is_separated,
        separated_by: item.separated_by,
        category: item.category ?? detectCategory(payloadName ?? item.item_name)
      };
      return [...prev, newItem];
    });
  };

  const handleItemDelete = (itemId: string) => {
    // Remover item da lista local pelo id
    setAllItems(prev => prev.filter(item => item.id !== itemId));
  };

  // Hook de realtime para sessões
  const updateUserPresence = async (..._args: any[]) => { };

  const [isRealtimeConnected, setIsRealtimeConnected] = useState(false);
  const [editingNameIds, setEditingNameIds] = useState<Set<string>>(new Set());
  const [editingQuantityIds, setEditingQuantityIds] = useState<Set<string>>(new Set());
  const [editingObservationIds, setEditingObservationIds] = useState<Set<string>>(new Set());

  // Refs para evitar closures desatualizadas nos handlers de realtime
  const editingNameIdsRef = useRef<Set<string>>(new Set());
  const editingQuantityIdsRef = useRef<Set<string>>(new Set());
  const editingObservationIdsRef = useRef<Set<string>>(new Set());

  // Handlers para controlar lock de edição de nome
  const onNameFocus = (id: string) => {
    setEditingNameIds(prev => {
      const next = new Set([...prev, id]);
      editingNameIdsRef.current = next;
      return next;
    });
  };

  const onNameBlur = (id: string) => {
    setEditingNameIds(prev => {
      const next = new Set(prev);
      next.delete(id);
      editingNameIdsRef.current = next;
      return next;
    });
  };

  // Handlers para lock de edição de quantidade enviada
  const onQuantityFocus = (id: string) => {
    setEditingQuantityIds(prev => {
      const next = new Set([...prev, id]);
      editingQuantityIdsRef.current = next;
      return next;
    });
  };

  const onQuantityBlur = (id: string) => {
    setEditingQuantityIds(prev => {
      const next = new Set(prev);
      next.delete(id);
      editingQuantityIdsRef.current = next;
      return next;
    });
  };

  // Handlers para lock de edição de observação
  const onObservationFocus = (id: string) => {
    setEditingObservationIds(prev => {
      const next = new Set([...prev, id]);
      editingObservationIdsRef.current = next;
      return next;
    });
  };

  const onObservationBlur = (id: string) => {
    setEditingObservationIds(prev => {
      const next = new Set(prev);
      next.delete(id);
      editingObservationIdsRef.current = next;
      return next;
    });
  };

  // Estados para o reasoning da IA
  const [showReasoning, setShowReasoning] = useState(false);
  const [reasoningContent, setReasoningContent] = useState('');

  // Estados para o thinking process em tempo real
  const [showThinking, setShowThinking] = useState(false);
  const [thinkingProcess, setThinkingProcess] = useState('');
  const [thinkingStartTime, setThinkingStartTime] = useState<number | null>(null);
  const [thinkingElapsedSeconds, setThinkingElapsedSeconds] = useState(0);
  const [reasoningTokenCount, setReasoningTokenCount] = useState<number | null>(null);
  const [currentAiModel, setCurrentAiModel] = useState<string | null>(null);
  const [showReasoningPanel, setShowReasoningPanel] = useState(false);
  const statusMessages = useMemo(() => [
    'Lendo sua mensagem...',
    'Identificando cada produto mencionado...',
    'Conectando com o catálogo Momma...',
    'Verificando aliases aprendidos...',
    'Calculando quantidades e unidades...',
    'Classificando por categoria automaticamente...',
    'Buscando matches no histórico de vendas...',
    'Validando consistência dos itens...',
    'Organizando a lista final...',
    'Quase pronto, finalizando...',
  ], []);
  const [statusMessageIndex, setStatusMessageIndex] = useState(0);
  const [isFading, setIsFading] = useState(false);
  useEffect(() => {
    const timers: number[] = [];
    let mounted = true;
    const fadeDuration = 1500;
    const holdDuration = 5000;
    const cycle = () => {
      if (!mounted) return;
      const tHold = window.setTimeout(() => {
        if (!mounted) return;
        setIsFading(true);
        const tFade = window.setTimeout(() => {
          if (!mounted) return;
          setStatusMessageIndex(i => (i + 1) % statusMessages.length);
          setIsFading(false);
          cycle();
        }, fadeDuration);
        timers.push(tFade);
      }, holdDuration);
      timers.push(tHold);
    };
    cycle();
    return () => {
      mounted = false;
      timers.forEach(id => clearTimeout(id));
    };
  }, [statusMessages]);

  function formatElapsed(seconds: number): string {
    const s = Math.max(0, Number(seconds) || 0);
    const mm = String(Math.floor(s / 60)).padStart(2, '0');
    const ss = String(s % 60).padStart(2, '0');
    return `${mm}:${ss}`;
  }

  // Estado para controlar a aba ativa (Logística começa em Revisão)
  const [activeTab, setActiveTab] = useState<string>(isLogistica ? 'result' : 'method');
  const [requestMode, setRequestMode] = useState<'ia' | 'manual' | null>(null);
  const [showQueueSuccess, setShowQueueSuccess] = useState(false);
  const [productPickerOpen, setProductPickerOpen] = useState(false);
  const [productSearch, setProductSearch] = useState('');
  const [catalogProducts, setCatalogProducts] = useState<{ id: number; nome: string; unidade_medida?: string; codigo_interno?: string; categoria_nome?: string }[]>([]);

  useEffect(() => {
    // Carregar catálogo sempre ao iniciar para garantir validação de dados legados
    const fetchCatalog = async () => {
      try {
        const query = (supabase as any)
          .from('produtos_master')
          .select('id, nome, unidade_medida, codigo_interno, categorias(nome)')
          .eq('ativo', true)
          .order('nome');
        const { data, error } = await query as any;
        if (error) {
          handleError(error, { domain: 'requisicoes', operation: 'carregarCatalogoProdutos', showToast: false });
          return;
        }
        // Flatten categoria name from join
        const flattenedData = (data || []).map((p: any) => ({
          ...p,
          categoria_nome: p.categorias?.nome || undefined
        }));
        setCatalogProducts(flattenedData);
      } catch (err) {
        handleError(err, { domain: 'requisicoes', operation: 'buscarProdutos', showToast: false });
      }
    };
    fetchCatalog();
  }, []);

  // AUTO-ENRICHMENT: Automatically lock and code items that match the catalog
  // Prioridade: 1) já locked, 2) match estrito, 3) match por alias (aprendizado), 4) fuzzy
  useEffect(() => {
    if (catalogProducts.length === 0 || allItems.length === 0) return;

    let hasChanges = false;
    const itemsToReview: AIProcessedItem[] = [];
    const normalize = (s: string) => s.toLowerCase().trim();

    const newAllItems = allItems.filter(item => {
      // If item is already locked/coded, keep it in the list
      if (item.code && item.isLocked && item.matchedId) return true;

      // 1) Try strict match first
      let match = catalogProducts.find(p => normalize(p.nome) === normalize(item.name));
      let bestScore = 1;

      // 2) Try alias match (aprendizado) — usa findProductByAlias do hook
      if (!match) {
        const aliasProductId = findProductByAlias(item.name);
        if (aliasProductId) {
          const aliasMatch = catalogProducts.find(p => p.id === aliasProductId);
          if (aliasMatch) {
            match = aliasMatch;
            bestScore = 1;
          }
        }
      }

      // 3) Fuzzy match ciente de categoria como último recurso.
      // bestCatalogMatch prefere o produto coerente com a seção ao vencedor
      // global de classe errada (ex.: "milho" → "Mini Caseirinho Milho", não
      // o insumo "Milho"). shouldAutoLock decide se trava ou manda pra revisão.
      if (!match) {
        const cm = bestCatalogMatch(
          { name: item.name, category: item.category },
          catalogProducts,
        );
        if (cm.product && shouldAutoLock(cm)) {
          match = cm.product;
          bestScore = cm.score;
        } else if (cm.product) {
          // Sugestão coerente mas abaixo do limiar ou bypass não aplicável →
          // revisão com produto pré-selecionado (1 clique para confirmar).
          hasChanges = true;
          itemsToReview.push({
            ...item,
            name: cm.product.nome,
            matchedId: cm.product.id.toString(),
            code: (cm.product as any).codigo_interno,
            matchConfidence: cm.score,
            isLowConfidence: true,
            isLocked: false,
            originalName: item.name,
          });
          return false;
        }
        // cm.product === null → match permanece null → cai no else abaixo
      }

      if (match) {
        hasChanges = true;
        const nameBeforeMatch = item.name;
        Object.assign(item, {
          name: match.nome,
          code: (match as any).codigo_interno,
          matchedId: match.id.toString(),
          category: (match as any).categoria_nome || item.category,
          manualCategory: (match as any).categoria_nome || item.manualCategory,
          isLocked: true,
          matchConfidence: bestScore,
          isLowConfidence: false,
          originalName: nameBeforeMatch.toLowerCase().trim() !== match.nome.toLowerCase().trim() ? nameBeforeMatch : undefined,
        });
        return true;
      } else {
        hasChanges = true;
        const reviewItem = { ...item, isLowConfidence: true, originalName: item.name };
        itemsToReview.push(reviewItem);
        return false;
      }
    });

    if (hasChanges) {
      wideDebug('requisicao.enriquecimento_strict', 'Enriquecimento Strict aplicado', { domain: 'requisicoes', attributes: { kept: newAllItems.length, movedToReview: itemsToReview.length } });
      setAllItems(newAllItems); // Update main list without zombies

      if (itemsToReview.length > 0) {
        setUnmatchedItems(prev => {
          // Avoid duplicates in review
          const combined = [...prev, ...itemsToReview];
          const unique = Array.from(new Map(combined.map(item => [item.id, item])).values());
          return unique;
        });
        toast.warning(`${itemsToReview.length} itens antigos precisam ser revisados.`);
      }
    }
  }, [catalogProducts, allItems]);

  const addItemFromCatalog = (p: { id: number; nome: string; unidade_medida?: string; codigo_interno?: string; categoria_nome?: string }) => {
    const masterCategory = p.categoria_nome || detectCategory(p.nome); // Prefer master category
    const temp: AIProcessedItem = {
      id: generateId(),
      name: p.nome,
      requested: 0,
      sent: '',
      observation: '',
      category: masterCategory,
      manualCategory: masterCategory,
      matchedId: p.id.toString(),
      code: p.codigo_interno,
      isLocked: true,
      matchConfidence: 1,
      // Herda unidade do produto_master no momento da criação; fallback 'cx'.
      // Salvar por item permite mesmo produto ter requisição em kg num dia e cx noutro.
      unidade_medida: (p.unidade_medida || 'cx').toLowerCase().trim() || 'cx',
    };
    setAllItems(prev => [...prev, temp]);
  };

  // Agente revisor (best-effort, assíncrono): segunda opinião sobre os matches que o
  // sistema "achou que sabia". Sinaliza itens onde, pelo nome, outro produto do catálogo
  // combina melhor — só avisa (reviewSuggestion), não altera nada sozinho.
  const runMatchReview = async (
    items: AIProcessedItem[],
    catalog: { id: number; nome: string; codigo_interno?: string }[],
  ) => {
    try {
      const SUPABASE_ANON_KEY = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY;
      // Revisa TODOS os itens matcheados — inclusive confiança 1.0 (alias/exato): um alias
      // envenenado ou match exato espúrio também pode estar errado, e o revisor é a rede de
      // segurança pós-match que precisa pegar isso (mesmo quando humano/aprendizado erraram).
      if (!SUPABASE_ANON_KEY || items.length === 0) return;

      const payload = {
        items: items.map((it) => ({
          texto: it.sourceText || it.originalName || it.name,
          match: it.name,
          // Título da seção a que o item pertence — dá ao revisor o contexto pra pegar
          // erros de herança de categoria (ex.: "chocolate" sob "Bolos no Pote" amarrado
          // em "Mini de Chocolate").
          categoria: it.category || '',
        })),
        productCatalog: catalog.map((p) => ({ name: p.nome })),
      };

      const resp = await fetch(`${supabase.supabaseUrl}/functions/v1/review-requisition-matches`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${SUPABASE_ANON_KEY}` },
        body: JSON.stringify(payload),
      });
      if (!resp.ok) return;

      const data = await resp.json();
      const flags: Array<{ index?: number; suggested_name?: string; reason?: string }> =
        Array.isArray(data?.flags) ? data.flags : [];
      if (flags.length === 0) return;

      // Resolve cada flag contra o array enviado (flag.index = posição no payload).
      const byId = new Map<string, { suggestedName: string; suggestedId: string; reason: string }>();
      for (const flag of flags) {
        const target = items[Number(flag?.index)];
        if (!target || !flag?.suggested_name) continue;
        const suggested = catalog.find(
          (p) => normalizeAlias(p.nome) === normalizeAlias(String(flag.suggested_name)),
        );
        // Ignora se não achou no catálogo ou se a sugestão é o próprio produto já matcheado.
        if (!suggested || suggested.id.toString() === target.matchedId) continue;
        byId.set(target.id, {
          suggestedName: suggested.nome,
          suggestedId: suggested.id.toString(),
          reason: String(flag.reason || ''),
        });
      }
      if (byId.size === 0) return;

      setAllItems((prev) =>
        prev.map((item) => (byId.has(item.id) ? { ...item, reviewSuggestion: byId.get(item.id) } : item)),
      );
      toast.info(`Revisor da IA sinalizou ${byId.size} match(es) pra você conferir.`);
    } catch {
      // best-effort: silencioso, nunca quebra o fluxo principal
    }
  };

  // Handler for changing the matched product of an existing item
  const handleChangeMatch = async (index: number, product: { id: number; nome: string; codigo_interno?: string; categoria_nome?: string }) => {
    // Aprendizado de alias. CRÍTICO: o termo NUNCA pode ser o produto matcheado atual
    // (originalItem.name) — é justamente o que estamos CORRIGINDO; aprender
    // "produto-errado -> produto-certo" envenena o catálogo (ex.: "Bombom de Uva" -> Morango).
    // Aprende o que o usuário DIGITOU (sourceText) + o nome interpretado pela IA (originalName,
    // que é o que findProductByAlias recebe na próxima vez). Pula se não houver origem confiável.
    const originalItem = allItems[index];
    if (originalItem) {
      const productNormalized = normalizeAlias(product.nome.trim());
      const vistos = new Set<string>();
      const termos = [originalItem.sourceText, originalItem.originalName]
        .map((t) => (t || "").trim())
        .filter((t) => {
          const n = normalizeAlias(t);
          if (n.length < 3 || n === productNormalized || vistos.has(n)) return false;
          vistos.add(n);
          return true;
        });
      if (termos.length > 0) {
        wideDebug('requisicao.aprendizado_alias', 'Aprendendo aliases', { domain: 'requisicoes', attributes: { termos, produtoOficial: product.nome } });
        // fire-and-forget; silent=true para dar 1 toast consolidado em vez de 1 por alias
        Promise.all(termos.map((t) => addAlias(product.id, t, true))).then((results) => {
          if (results.some(Boolean)) {
            toast.success(`Sistema aprendeu que "${termos[0]}" é "${product.nome.trim()}"!`);
            fetchAliases();
          }
        });
      }
    }

    const masterCategory = product.categoria_nome || detectCategory(product.nome); // Prefer master category
    setAllItems(prev => prev.map((item, i) => {
      if (i === index) {
        return {
          ...item,
          name: product.nome,
          matchedId: product.id.toString(),
          code: product.codigo_interno,
          category: masterCategory,
          manualCategory: masterCategory,
          isLocked: true,
          matchConfidence: 1,
          isLowConfidence: false,
          reviewSuggestion: undefined
        };
      }
      return item;
    }));
    toast.success(`Produto alterado para: ${product.nome}`);
  };

  // Carregar histórico do banco de dados e dados persistidos ao inicializar
  useEffect(() => {
    loadHistoryFromDatabase();
    // loadPersistedData(); REMOVED: User requested to stop loading from cache to avoid mixing old/new requests
    setupRealtimeSubscription();

    // Cleanup na desmontagem do componente
    return () => {
      cleanupRealtimeSubscription();
    };
  }, []);

  // Regra: para requisições da LAGO SUL, local de preparo deve ser Fábrica
  useEffect(() => {
    const normalizedRequester = normalizeStoreName(storeRequester) || storeRequester;
    if (normalizedRequester === 'LAGO SUL') {
      setStorePreparer('Fábrica');
    }
  }, [storeRequester]);

  // Garantir que o local de preparo permaneça Fábrica quando vazio
  useEffect(() => {
    if (!storePreparer) setStorePreparer('Fábrica');
  }, [storePreparer]);

  // ---------------------------------------------------------------------------
  // BLOQUEIO DE CARREGAMENTO DE SESSÃO ANTERIOR
  // O usuário solicitou explicitamente remover qualquer carregamento automático
  // de dados da sessão anterior ou recuperação de estado.
  // ---------------------------------------------------------------------------

  /*
  // Carregar itens da sessão ativa quando currentSessionId muda
  useEffect(() => {
    const loadSessionItems = async () => {
      if (currentSessionId && isSessionMode) {
        try {
          // Carregar a sessão
          await loadSession(currentSessionId);

          // Obter itens da sessão como AIProcessedItem
          const sessionItemsAsAI = getItemsAsAIProcessed();

          if (sessionItemsAsAI && sessionItemsAsAI.length > 0) {
            setAllItems(sessionItemsAsAI);
            wideDebug('requisicao.sessao_itens_carregados', 'Itens da sessao carregados', { domain: 'requisicoes', attributes: { count: sessionItemsAsAI.length } });
          }
        } catch (error) {
          handleError(error, { domain: 'requisicoes', operation: 'carregarItensSessao', showToast: false });
          toast.error('Erro ao carregar itens da sessão ativa');
        }
      }
    };

    loadSessionItems();
  }, [currentSessionId, isSessionMode, loadSession, getItemsAsAIProcessed]);

  // Verificar parâmetros de URL para carregar sessão específica
  useEffect(() => {
    const urlParams = new URLSearchParams(window.location.search);
    const sessionIdFromUrl = urlParams.get('session_id');

    if (sessionIdFromUrl) {
      wideDebug('requisicao.sessao_url', 'Carregando sessao da URL', { domain: 'requisicoes', attributes: { sessionId: sessionIdFromUrl } });

      // Carregar dados da sessão primeiro
      const loadSessionFromUrl = async () => {
        try {
          await loadSession(sessionIdFromUrl);
          const sessionData = currentSession;

          setIsSessionMode(true);
          setCurrentSessionId(sessionIdFromUrl);

          // Entrar na sessão no contexto global se não estiver
          if (!isInSession || globalSessionId !== sessionIdFromUrl) {
            if (sessionData) {
              enterSession(sessionIdFromUrl, sessionData);
            } else {
              enterSession(sessionIdFromUrl);
            }

            // Notificação de entrada na sessão
            toast.info('🔄 Entrando na sessão colaborativa...', {
              description: 'Sincronizando dados da sessão',
              duration: 3000,
            });
          }

          // Limpar parâmetro da URL após carregar
          const newUrl = window.location.pathname;
          window.history.replaceState({}, '', newUrl);
        } catch (error) {
          handleError(error, { domain: 'requisicoes', operation: 'carregarSessaoUrl', showToast: false });
          toast.error('Erro ao carregar sessão');
        }
      };

      loadSessionFromUrl();
    } else if (isInSession && globalSessionId) {
      // Se não há session_id na URL mas o contexto global indica que estamos em sessão ativa, carregar ela
      wideDebug('requisicao.sessao_contexto_global', 'Carregando sessao do contexto global', { domain: 'requisicoes', attributes: { sessionId: globalSessionId } });
      setIsSessionMode(true);
      setCurrentSessionId(globalSessionId);
    } else if (!isInSession && isSessionMode) {
      // Se o contexto global indica que não estamos em sessão, mas o estado local ainda reflete sessão ativa
      wideDebug('requisicao.sessao_limpeza', 'Contexto global indica que nao estamos em sessao - limpando estado local', { domain: 'requisicoes' });
      setIsSessionMode(false);
      setCurrentSessionId(null);
    }
  }, [globalSessionId, isInSession, enterSession]); // Executar quando globalSessionId ou isInSession mudarem
  */

  // Carregar requisição específica por ID (edição direta a partir dos relatórios)
  useEffect(() => {
    const urlParams = new URLSearchParams(window.location.search);
    const requisicaoIdParam = urlParams.get('requisicao_id');
    if (!requisicaoIdParam) return;

    const loadById = async (id: number) => {
      try {
        const { data: req, error } = await (supabase as any)
          .from('requisicoes')
          .select(`
            id,
            nome,
            solicitante,
            preparador,
            loja_solicitante,
            loja_preparadora,
            data_pedido,
            data_recebimento,
            status,
            requisicoes_itens (
              id,
              nome_produto,
              quantidade_solicitada,
              quantidade_enviada,
              observacao,
              ordem,
              category
            )
          `)
          .eq('id', id)
          .single();

        if (error || !req) {
          handleError(error, { domain: 'requisicoes', operation: 'carregarRequisicaoPorId', showToast: false });
          toast.error('Requisição não encontrada');
          return;
        }

        // Sair do modo sessão caso esteja ativo
        setIsSessionMode(false);
        setCurrentSessionId(null);
        // Garantir que o contexto global de sessão seja limpo
        try { exitSession(); } catch { }

        setRequesterName(req.solicitante || requesterName);
        setPreparerName(req.preparador || preparerName);
        setStoreRequester(req.loja_solicitante || storeRequester);
        setStorePreparer(req.loja_preparadora || 'Fábrica');
        setOrderDate(req.data_pedido || getCurrentLocalDate());
        setReceivedDate(
          req.data_recebimento || getTomorrowLocalDate()
        );

        const mappedItems: AIProcessedItem[] = (req.requisicoes_itens || [])
          .sort((a: any, b: any) => (a.ordem ?? 0) - (b.ordem ?? 0))
          .map((item: any) => ({
            id: String(item.id),
            name: item.nome_produto,
            requested: Number(item.quantidade_solicitada) || 0,
            sent: item.quantidade_enviada ?? '',
            observation: item.observacao || '',
            category: item.category || detectCategory(item.nome_produto),
            manualCategory: item.category || undefined
          }));

        setAllItems(mappedItems);

        // Marcar que estamos editando uma requisição existente
        setCurrentRequisicaoId(String(req.id));
        setCurrentRequisicaoStatus(String(req.status || 'em_fila'));

        // Limpar o parâmetro da URL para evitar recarregamentos acidentais
        const newUrl = window.location.pathname;
        window.history.replaceState({}, '', newUrl);

        toast.success(`Requisição "${req.nome}" carregada para edição`);
      } catch (err) {
        handleError(err, { domain: 'requisicoes', operation: 'carregarRequisicaoPorId', showToast: false });
        toast.error('Erro ao carregar requisição');
      }
    };

    const id = Number(requisicaoIdParam);
    if (!Number.isNaN(id)) {
      loadById(id);
    } else {
      toast.error('ID de requisição inválido');
    }
  }, []);

  /*
  // Sincronizar estado local com contexto global
  useEffect(() => {
    // Se o contexto global indica que estamos em sessão, mas o estado local não reflete isso
    if (isInSession && globalSessionId && (!isSessionMode || currentSessionId !== globalSessionId)) {
      wideDebug('requisicao.sessao_sync_entrada', 'Sincronizando estado local com contexto global - entrando em sessao', { domain: 'requisicoes', attributes: { sessionId: globalSessionId } });
      setIsSessionMode(true);
      setCurrentSessionId(globalSessionId);
    }
    // Se o contexto global indica que não estamos em sessão, mas o estado local ainda reflete sessão ativa
    else if (!isInSession && isSessionMode) {
      wideDebug('requisicao.sessao_sync_saida', 'Sincronizando estado local com contexto global - saindo de sessao', { domain: 'requisicoes' });
      setIsSessionMode(false);
      setCurrentSessionId(null);
    }
  }, [isInSession, globalSessionId, isSessionMode, currentSessionId]);

  // Atualizar presença do usuário periodicamente quando em sessão ativa
  useEffect(() => {
    if (isSessionMode && currentSessionId && userProfile?.nome) {
      // Atualizar presença imediatamente
      updateUserPresence(currentSessionId, userProfile.nome);

      // Configurar intervalo para atualizar presença a cada 30 segundos
      const interval = setInterval(() => {
        updateUserPresence(currentSessionId, userProfile.nome);
      }, 30000);

      return () => clearInterval(interval);
    }
  }, [isSessionMode, currentSessionId, userProfile?.nome, updateUserPresence]);

  // Sincronizar sessionItems com allItems quando sessionItems muda
  useEffect(() => {
    if (isSessionMode && sessionItems && sessionItems.length > 0) {
      const sessionItemsAsAI = getItemsAsAIProcessed();
      if (sessionItemsAsAI) {
        setAllItems(sessionItemsAsAI);
        wideDebug('requisicao.sessao_itens_sincronizados', 'Itens da sessao sincronizados automaticamente', { domain: 'requisicoes', attributes: { count: sessionItemsAsAI.length } });
      }
    }
  }, [sessionItems, isSessionMode, getItemsAsAIProcessed]);

  // Preencher campos do formulário quando currentSession é carregada
  useEffect(() => {
    if (currentSession && isSessionMode) {
      setRequesterName(currentSession.requester_name || 'Henderson');
      setPreparerName(currentSession.preparer_name || 'Separador');
      setStoreRequester(currentSession.store_requester || '');
      setStorePreparer(currentSession.store_preparer || '');
      setOrderDate(currentSession.order_date || '');
      setReceivedDate(currentSession.received_date || '');
      wideDebug('requisicao.sessao_formulario_preenchido', 'Campos do formulario preenchidos com dados da sessao', { domain: 'requisicoes' });
    }
  }, [currentSession, isSessionMode]);
  */

  // Atualizar contador de segundos do thinking process
  useEffect(() => {
    let interval: NodeJS.Timeout;

    if (thinkingStartTime && isProcessing) {
      interval = setInterval(() => {
        const elapsed = Math.floor((Date.now() - thinkingStartTime) / 1000);
        setThinkingElapsedSeconds(elapsed);
      }, 1000);
    }

    return () => {
      if (interval) {
        clearInterval(interval);
      }
    };
  }, [thinkingStartTime, isProcessing]);



  // Configurar sincronização em tempo real
  const setupRealtimeSubscription = () => {
    try {
      const channel = supabase
        .channel('requisicoes_realtime')
        .on(
          'postgres_changes',
          {
            event: '*',
            schema: 'public',
            table: 'requisicoes_itens'
          },
          (payload) => {
            handleRealtimeUpdate(payload);
          }
        )
        .on(
          'postgres_changes',
          {
            event: '*',
            schema: 'public',
            table: 'digital_separation_items'
          },
          (payload) => {
            handleSeparationItemUpdate(payload);
          }
        )
        .subscribe((status) => {
          if (status === 'SUBSCRIBED') {
            setIsRealtimeConnected(true);
            wideDebug('requisicao.realtime_conectado', 'Conectado ao Supabase Realtime para requisicoes e separacoes', { domain: 'requisicoes' });
          } else if (status === 'CHANNEL_ERROR') {
            setIsRealtimeConnected(false);
            wideError('requisicao.realtime_erro', 'Erro na conexao Realtime', { domain: 'requisicoes' });
          }
        });

      setRealtimeChannel(channel);
    } catch (error) {
      handleError(error, { domain: 'requisicoes', operation: 'configurarRealtime', showToast: false });
    }
  };

  // Limpar subscription do Realtime
  const cleanupRealtimeSubscription = () => {
    if (realtimeChannel) {
      supabase.removeChannel(realtimeChannel);
      setRealtimeChannel(null);
      setIsRealtimeConnected(false);
    }
  };

  // Lidar com atualizações em tempo real
  const handleRealtimeUpdate = (payload: any) => {
    wideDebug('requisicao.realtime_update', 'Atualizacao em tempo real recebida', { domain: 'requisicoes', attributes: { eventType: payload.eventType } });

    // Verificar se a atualização é relevante para a sessão atual
    if (payload.new && (payload.eventType === 'UPDATE' || payload.eventType === 'INSERT')) {
      const updatedItem = payload.new;

      // Atualizar o item correspondente na lista local
      setAllItems(currentItems => {
        // Usar apenas IDs estáveis para casar os itens. Tentar obter o ID de sessão
        const sessionItemId = updatedItem.session_item_id || updatedItem.active_session_item_id || updatedItem.item_id;

        // Se não houver mapeamento de ID de sessão, ignorar para evitar piscadas
        if (!sessionItemId) {
          return currentItems;
        }

        const itemIndex = currentItems.findIndex(item => item.id === sessionItemId);

        if (itemIndex !== -1) {
          const updatedItems = [...currentItems];
          updatedItems[itemIndex] = {
            ...updatedItems[itemIndex],
            // Se o usuário estiver editando o nome localmente, não sobrescrever com o valor remoto
            name: (editingNameIdsRef.current && editingNameIdsRef.current.has(sessionItemId))
              ? updatedItems[itemIndex].name
              : (updatedItem.nome_produto || updatedItems[itemIndex].name),
            requested: updatedItem.quantidade_solicitada,
            sent: (editingQuantityIdsRef.current && editingQuantityIdsRef.current.has(sessionItemId))
              ? updatedItems[itemIndex].sent
              : (updatedItem.quantidade_enviada ?? updatedItems[itemIndex].sent ?? ''),
            observation: (editingObservationIdsRef.current && editingObservationIdsRef.current.has(sessionItemId))
              ? updatedItems[itemIndex].observation
              : (updatedItem.observacao ?? updatedItems[itemIndex].observation ?? ''),
            // Adicionar informações de separação se disponíveis
            is_separated: updatedItem.is_separated,
            separated_by: updatedItem.separated_by,
            separated_at: updatedItem.separated_at
          };

          // Mostrar notificação específica baseada no tipo de atualização
          if (updatedItem.is_separated && updatedItem.separated_by) {
            toast.success(`Item "${updatedItem.nome_produto}" separado por ${updatedItem.separated_by}!`, {
              description: `Quantidade enviada: ${updatedItem.quantidade_enviada || 'Não informada'}`
            });
          } else if (updatedItem.observacao) {
            toast.info(`Observação atualizada para "${updatedItem.nome_produto}"`, {
              description: updatedItem.observacao
            });
          } else {
            toast.success('Item atualizado em tempo real!');
          }

          return updatedItems;
        }

        return currentItems;
      });
    }
  };

  // Lidar com atualizações dos itens de separação digital
  const handleSeparationItemUpdate = (payload: any) => {
    wideDebug('requisicao.separacao_update', 'Atualizacao de separacao recebida', { domain: 'requisicoes', attributes: { eventType: payload.eventType } });

    if (payload.new && (payload.eventType === 'UPDATE' || payload.eventType === 'INSERT')) {
      const separationItem = payload.new;

      // Atualizar o item correspondente na lista local
      setAllItems(currentItems => {
        // Casar exclusivamente pelo ID do item de sessão usado na separação
        const sessionItemId = separationItem.session_item_id || separationItem.active_session_item_id || separationItem.item_id;

        if (!sessionItemId) {
          return currentItems;
        }

        const itemIndex = currentItems.findIndex(item => item.id === sessionItemId);

        if (itemIndex !== -1) {
          const updatedItems = [...currentItems];
          updatedItems[itemIndex] = {
            ...updatedItems[itemIndex],
            // Honrar lock de edição: manter nome local enquanto o usuário digita
            name: (editingNameIdsRef.current && editingNameIdsRef.current.has(sessionItemId))
              ? updatedItems[itemIndex].name
              : (separationItem.item_name || updatedItems[itemIndex].name),
            sent: (editingQuantityIdsRef.current && editingQuantityIdsRef.current.has(sessionItemId))
              ? updatedItems[itemIndex].sent
              : (separationItem.sent_quantity ?? updatedItems[itemIndex].sent ?? ''),
            observation: (editingObservationIdsRef.current && editingObservationIdsRef.current.has(sessionItemId))
              ? updatedItems[itemIndex].observation
              : (separationItem.observation ?? updatedItems[itemIndex].observation ?? ''),
            is_separated: separationItem.is_separated,
            separated_by: separationItem.separated_by,
            separated_at: separationItem.separated_at,
            // Sincronizar categorias vindas da separação, respeitando edição local de categoria
            category: (editingCategory !== null)
              ? updatedItems[itemIndex].category
              : (separationItem.category ?? updatedItems[itemIndex].category),
            manualCategory: (editingCategory !== null)

