/**
 * @module logistics-utils
 *
 * Utilitários de logística: normalização de status de requisições e
 * geração de etapas (stops) para a timeline de expedições.
 *
 * O sistema usa **3 estados padronizados** para requisições:
 *
 * | Estado         | Significado                     |
 * |----------------|---------------------------------|
 * | `em_fila`      | Aguardando início da separação  |
 * | `em_progresso` | Separação em andamento          |
 * | `finalizada`   | Separação concluída             |
 *
 * Valores legados (`concluida`, `aprovada`, `entregue`, `separacao`, `pendente`)
 * são mapeados automaticamente para o estado padronizado correspondente.
 */

import {
  RequisicaoSimple,
  ShipmentStatus,
  Stop,
  ActivityLog,
} from '@/shared/types/logistics';

/** Status padronizado de uma requisição. */
export type NormalizedRequisicaoStatus =
  | 'em_fila'
  | 'em_progresso'
  | 'finalizada';

/**
 * Constantes para os 3 estados padronizados de requisição.
 * Use estas constantes ao invés de strings literais para evitar typos.
 */
export const REQUISICAO_STATUS = {
  EM_FILA: 'em_fila',
  EM_PROGRESSO: 'em_progresso',
  FINALIZADA: 'finalizada',
} as const;

/**
 * Normaliza qualquer string de status (incluindo valores legados) para um
 * dos 3 estados padronizados.
 *
 * @param status - Status bruto vindo do banco de dados.
 * @returns Status normalizado: `"em_fila"` | `"em_progresso"` | `"finalizada"`.
 *
 * @example
 * ```ts
 * normalizeRequisicaoStatus("concluida");   // "finalizada"
 * normalizeRequisicaoStatus("separacao");   // "em_progresso"
 * normalizeRequisicaoStatus("pendente");    // "em_fila"
 * normalizeRequisicaoStatus("em_progresso"); // "em_progresso"
 * ```
 */
export const normalizeRequisicaoStatus = (
  status: string,
): NormalizedRequisicaoStatus => {
  const s = (status || '').toLowerCase().trim();
  if (['finalizada', 'concluida', 'aprovada', 'entregue'].includes(s))
    return 'finalizada';
  if (['em_progresso', 'separacao', 'em_separacao'].includes(s))
    return 'em_progresso';
  return 'em_fila';
};

/**
 * Mapeia o status padronizado da requisição para o status visual de um sub-step na timeline.
 *
 * @param reqStatus - Status bruto da requisição.
 * @returns `"pending"` | `"in_progress"` | `"completed"`.
 *
 * @internal Usado por {@link generateStops}.
 */
const mapRequisicaoToSubStepStatus = (
  reqStatus: string,
): 'pending' | 'in_progress' | 'completed' => {
  const normalized = normalizeRequisicaoStatus(reqStatus);
  switch (normalized) {
    case 'finalizada':
      return 'completed';
    case 'em_progresso':
      return 'in_progress';
    case 'em_fila':
    default:
      return 'pending';
  }
};

/**
 * Verifica se uma requisição está no estado finalizado (qualquer variante legada inclusa).
 *
 * @param status - Status bruto da requisição.
 */
export const isRequisicaoFinalizada = (status: string): boolean => {
  return normalizeRequisicaoStatus(status) === 'finalizada';
};

/**
 * Gera a lista de **stops** (etapas) de uma expedição para exibição na timeline.
 *
 * Estrutura gerada:
 * 1. **Separação** — com sub-steps por loja/requisição
 * 2. **Carregamento** — sub-steps por loja
 * 3. **Conf. & Despacho** — etapa única
 * 4. **Lojas** (uma por requisição) — com timestamps de chegada/saída extraídos dos logs
 *
 * @param reqs       - Lista de requisições vinculadas à expedição.
 * @param status     - Status global da expedição (determina qual etapa é `current`).
 * @param logs       - Logs de atividade para determinar timestamps de chegada/saída.
 * @param routeOrder - Ordem preferencial de lojas na rota (nomes).
 * @returns Array de {@link Stop} ordenados pela sequência da expedição.
 */
export const generateStops = (
  reqs: RequisicaoSimple[],
  status: ShipmentStatus = 'separation',
  logs: ActivityLog[] = [],
  routeOrder: string[] = [],
): Stop[] => {
  const steps: Stop[] = [];
  const totalItems = reqs.reduce((acc, r) => acc + r.item_count, 0);

  // Ordenar requisições baseado na ordem da rota (se fornecida)
  const sortedReqs = [...reqs];
  if (routeOrder && routeOrder.length > 0) {
    sortedReqs.sort((a, b) => {
      const indexA = routeOrder.indexOf(a.loja_solicitante);
      const indexB = routeOrder.indexOf(b.loja_solicitante);
      if (indexA !== -1 && indexB !== -1) return indexA - indexB;
      if (indexA !== -1) return -1;
      if (indexB !== -1) return 1;
      return 0;
    });
  }

  // 1. SEPARAÇÃO
  const sepStatus = status === 'separation' ? 'current' : 'completed';
  const sepSubSteps = sortedReqs.map((r) => ({
    id: `sep_${r.id}`,
    label: r.loja_solicitante,
    status: mapRequisicaoToSubStepStatus(r.status),
  }));

  steps.push({
    id: 'process_separation',
    name: 'Separação',
    type: 'process',
    status: sepStatus,
    itemsCount: totalItems,
    subSteps: sepSubSteps,
  });

  // 2. CARREGAMENTO
  const loadStatus =
    status === 'separation'
      ? 'pending'
      : status === 'loading'
        ? 'current'
        : 'completed';
  steps.push({
    id: 'process_loading',
    name: 'Carregamento',
    type: 'process',
    status: loadStatus,
    itemsCount: totalItems,
    subSteps: sortedReqs.map((r) => ({
      id: `load_${r.id}`,
      label: r.loja_solicitante,
      status: 'pending' as const,
    })),
  });

  // 3. DESPACHO
  const dispatchStatus = ['separation', 'loading'].includes(status)
    ? 'pending'
    : status === 'dispatch'
      ? 'current'
      : 'completed';

  steps.push({
    id: 'process_dispatch',
    name: 'Conf. & Despacho',
    type: 'process',
    status: dispatchStatus,
    itemsCount: 0,
  });

  // 4. LOJAS — uma etapa de entrega por requisição
  sortedReqs.forEach((r) => {
    let storeStatus: 'pending' | 'current' | 'completed' | 'next' =
      status === 'completed' ? 'completed' : 'pending';

    let arrivalTime: string | undefined;
    let departureTime: string | undefined;

    if (status !== 'completed' && logs.length > 0) {
      const storeName = r.loja_solicitante.toLowerCase();

      const arrivalLog = logs.find(
        (l) =>
          l.type === 'arrival_confirmation' &&
          l.metadata?.store_name?.toLowerCase().includes(storeName),
      );
      const departureLog = logs.find(
        (l) =>
          l.type === 'departure_confirmation' &&
          l.metadata?.store_name?.toLowerCase().includes(storeName),
      );

      if (departureLog) {
        storeStatus = 'completed';
        departureTime = departureLog.timestamp;
      }
      if (arrivalLog) {
        if (!departureLog) storeStatus = 'current';
        arrivalTime = arrivalLog.timestamp;
      }
    }

    steps.push({
      id: `store_${r.id}`,
      name: `Loja ${r.loja_solicitante}`,
      type: 'store',
      status: storeStatus,
      itemsCount: r.item_count,
      arrivalTime,
      departureTime,
    });
  });

  return steps;
};

